    #[test]
    fn declined_disc_combinator_leaves_disconnected_blocks_that_cleanup_removes() {
        let mut graph = FunctionGraph::new("result_map_missing_closure");
        let entry = graph.startblock;
        let recv = graph
            .push_op_var(entry, OpKind::ConstInt(0), true)
            .expect("receiver");
        let result = graph
            .push_op_var(
                entry,
                OpKind::Call {
                    target: CallTarget::method("map", Some("core::result::Result".to_string())),
                    args: crate::model::call_args(vec![recv]),
                    result_ty: ValueType::Ref(None),
                },
                true,
            )
            .expect("map");
        let cont = graph.create_block();
        graph.set_goto(entry, cont, vec![]);
        graph.set_return(cont, None);
        let site = super::DiscCombinatorSite {
            kind: super::DiscCombinator::ResultMap,
            result_var: result,
            call_args: Vec::new(),
            recv_owner: "core::result::Result".into(),
            recv_tag0_owner: "core::result::Result::Ok".into(),
            recv_tag1_owner: "core::result::Result::Err".into(),
            payload0_ty: ValueType::Int,
            payload1_ty: ValueType::Int,
            payload0_class: None,
            payload1_class: None,
            result_owner: "core::result::Result".into(),
            result_tag0_owner: "core::result::Result::Ok".into(),
            result_tag1_owner: "core::result::Result::Err".into(),
            result_payload0_ty: ValueType::Int,
            result_payload1_ty: ValueType::Int,
            result_payload0_class: None,
            result_payload1_class: None,
            call_once_owner: String::new(),
            fn_item_segments: None,
            fn_item_ctor: None,
            args_tuple_suffix: String::new(),
            call_result_ty: ValueType::Int,
            call_result_class: None,
            carrier_recv: false,
            recv_niche: false,
            scalar_niche: false,
            result_niche: false,
            result_scalar_niche: false,
            niche_null_cast: None,
            int_null: None,
        };
        let live_before: std::collections::HashSet<_> =
            graph.blocks.iter().map(|block| block.id).collect();
        let rewritten = super::rewire_disc_combinator_sites(
            &mut graph,
            &[site],
            crate::ErrorCarrierSpec::default(),
        );
        assert_eq!(rewritten, 0);
        let leftovers: Vec<_> = graph
            .blocks
            .iter()
            .filter(|block| !live_before.contains(&block.id))
            .map(|block| block.id)
            .collect();
        assert!(
            !leftovers.is_empty(),
            "a declined combinator site must leave the blocks it created"
        );
        crate::model::clear_unreachable_blocks(&mut graph);
        for id in leftovers {
            let block = graph.block(id);
            assert!(
                block.operations.is_empty() && block.exits.is_empty(),
                "clear_unreachable_blocks must empty disconnected decline leftovers"
            );
        }
    }

    fn boxing_cluster_with_nested_header() -> FunctionGraph {
        let mut graph = FunctionGraph::new("w_new_int");
        let entry = graph.startblock;
        let header_owner = "ObjectHeader";
        let outer_owner = "W_IntObject";
        let header = graph
            .push_op_var(
                entry,
                OpKind::Call {
                    target: CallTarget::synthetic_transparent_struct_ctor(Vec::new(), header_owner),
                    args: Vec::new(),
                    result_ty: ValueType::Ref(Some(header_owner.to_string())),
                },
                true,
            )
            .expect("header ctor");
        let class_static = graph
            .push_op_var(
                entry,
                OpKind::Call {
                    target: CallTarget::function_path(["charon_corpus", "INT_CLASS"]),
                    args: Vec::new(),
                    result_ty: ValueType::Ref(None),
                },
                true,
            )
            .expect("class static");
        graph.push_op_var(
            entry,
            OpKind::FieldWrite {
                base: header.clone(),
                field: FieldDescriptor::new("ob_type", Some(header_owner.to_string())),
                value: LinkArg::Value(class_static),
                ty: ValueType::Ref(None),
            },
            false,
        );
        let outer = graph
            .push_op_var(
                entry,
                OpKind::Call {
                    target: CallTarget::synthetic_transparent_struct_ctor(Vec::new(), outer_owner),
                    args: Vec::new(),
                    result_ty: ValueType::Ref(Some(outer_owner.to_string())),
                },
                true,
            )
            .expect("outer ctor");
        graph.push_op_var(
            entry,
            OpKind::FieldWrite {
                base: outer.clone(),
                field: FieldDescriptor::new("ob_header", Some(outer_owner.to_string())),
                value: LinkArg::Value(header),
                ty: ValueType::Ref(None),
            },
            false,
        );
        let boxed = graph
            .push_op_var(
                entry,
                OpKind::Call {
                    target: CallTarget::function_path(["runtime_object", "lltype", "malloc_typed"]),
                    args: crate::model::call_args(vec![outer.clone()]),
                    result_ty: ValueType::Ref(Some(outer_owner.to_string())),
                },
                true,
            )
            .expect("malloc_typed");
        graph.set_return(entry, Some(boxed));
        graph
    }

    fn boxing_cluster_ctor_new_counts(graph: &FunctionGraph) -> (usize, usize) {
        let mut ctors = 0usize;
        let mut news = 0usize;
        for op in graph.blocks.iter().flat_map(|block| &block.operations) {
            match &op.kind {
                OpKind::Call {
                    target:
                        CallTarget::SyntheticTransparentCtor {
                            is_struct: true, ..
                        },
                    ..
                } => ctors += 1,
                OpKind::New { .. } => news += 1,
                _ => {}
            }
        }
        (ctors, news)
    }

    /// The nested header stored into a `malloc_typed` aggregate is still
    /// part of the boxing cluster. Rewriting it to `New` would allocate the
    /// header separately and leave fusion looking at a `New` instead of a
    /// constructor.
    #[test]
    fn malloc_typed_nested_header_ctor_is_left_for_boxing_fusion() {
        let mut graph = boxing_cluster_with_nested_header();
        assert_eq!(boxing_cluster_ctor_new_counts(&graph), (2, 0));
        assert_eq!(replace_struct_ctors(&mut graph), 0);
        assert_eq!(boxing_cluster_ctor_new_counts(&graph), (2, 0));
    }

    /// Final simplify must not steal the cluster either: fusion still has
    /// to see the construct-on-stack spelling after class addresses land.
    #[test]
    fn final_simplify_leaves_boxing_cluster_ctors_including_nested_header() {
        let mut graph = boxing_cluster_with_nested_header();
        simplify_lowered_graph(
            &mut graph,
            &std::collections::HashMap::new(),
            true,
            &std::collections::HashSet::new(),
        );
        assert_eq!(boxing_cluster_ctor_new_counts(&graph), (2, 0));
    }

    #[test]
    fn fn_ptr_value_type_is_int_and_input_class_root_is_fn() {
        let llbc = fixture_llbc();
        let ty = TyRef::Other(serde_json::json!({
            "FnPtr": {
                "skip_binder": {
                    "inputs": [{"Slice": [{"Adt": {"id": 0}}]}],
                    "output": {"Scalar": {"Integer": {"Signed": "I64"}}},
                    "is_unsafe": false
                }
            }
        }));
        assert_eq!(
            tyref_to_value_type(&ty, &llbc),
            ValueType::Int,
            "history.getkind of Ptr(FuncType) is int"
        );
        assert_eq!(
            tyref_fn_ptr_input_class_root(&ty, &llbc).as_deref(),
            Some("fn([??adt#0]) -> i64"),
            "Int-banked fn-pointer params carry the fn(inputs) -> output spelling"
        );
        assert_eq!(
            tyref_to_attr_value_type(&ty, &llbc),
            ValueType::Int,
            "a stored fn field uses the same Int bank as a value site"
        );
    }

    /// Every row of the fn-pointer family decision, including the two the
    /// fixture corpus structurally cannot reach: it declares one fn-pointer
    /// alias (`HostCallback`) and that alias is safe, so no corpus-driven
    /// test distinguishes `is_safe` either way.
    ///
    /// The load-bearing row is `(unsafe, builtin shape) -> None`. Its
    /// positive control is the row above it: drop the safety gate and
    /// `(safe, builtin shape)` still passes while that row flips to
    /// `Some(BuiltinWrapper)`, so the pair fails in exactly one direction.
    #[test]
    fn fn_ptr_family_names_the_wrapper_set_only_for_a_safe_pointer() {
        // (is_safe, is_builtin_shape, fnptr_indirect) -> family
        let rows = [
            (true, true, false, Some(FnPtrFamily::BuiltinWrapper)),
            (true, true, true, Some(FnPtrFamily::BuiltinWrapper)),
            (false, true, false, None),
            (false, true, true, None),
            (true, false, true, Some(FnPtrFamily::Unknown)),
            // An `unsafe fn` outside the wrapper shape keeps the unknown
            // family: `None` graphs claims nothing about the callee.
            (false, false, true, Some(FnPtrFamily::Unknown)),
            (true, false, false, None),
            (false, false, false, None),
        ];
        for (is_safe, is_builtin_shape, fnptr_indirect, expected) in rows {
            assert_eq!(
                fn_ptr_family_for(is_safe, is_builtin_shape, fnptr_indirect),
                expected,
                "is_safe={is_safe} is_builtin_shape={is_builtin_shape} \
                 fnptr_indirect={fnptr_indirect}"
            );
        }
    }

