    #[test]
    fn a_tuple_param_names_the_shape_its_reads_name() {
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [], "fun_decls": [], "global_decls": [],
                "trait_decls": [], "trait_impls": [],
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
        let tuple = serde_json::json!({
            "Adt": {
                "id": 0, "builtin": "Tuple",
                "generics": {
                    "types": [
                        { "Scalar": { "Integer": { "Signed": "I64" } } },
                        { "Scalar": "Bool" }
                    ]
                }
            }
        });
        let owner = format!(
            "Tuple{}",
            tyref_tuple_suffix(&TyRef::Other(tuple.clone()), &llbc)
        );
        assert!(majit_ir::descr::is_shaped_tuple_name(&owner), "{owner}");
        // By value (a closure's args tuple) and behind a borrow (the read
        // place of `(*p).N` is the deref'd tuple) both name the read owner.
        let by_value = TyRef::Other(tuple.clone());
        let borrowed = TyRef::Other(serde_json::json!({ "Ref": ["Erased", tuple, "Shared"] }));
        assert_eq!(
            tyref_shaped_tuple_root(&by_value, &llbc),
            Some(owner.clone())
        );
        assert_eq!(
            tyref_shaped_tuple_root(&borrowed, &llbc),
            Some(owner.clone())
        );
        let unit = TyRef::Other(serde_json::json!({
            "Adt": { "id": 0, "builtin": "Tuple", "generics": { "types": [] } }
        }));
        assert_eq!(tyref_shaped_tuple_root(&unit, &llbc), None);
        let int = TyRef::Other(serde_json::json!({ "Scalar": { "Integer": { "Signed": "I64" } } }));
        assert_eq!(tyref_shaped_tuple_root(&int, &llbc), None);
        // The TypeDecl leaf of a builtin Tuple is `"Tuple"`. Input
        // class_root must keep the shaped name so `call_once` args
        // seed `SomeTuple` (`rtuple.py` `TupleRepr`).
        assert_eq!(
            tyref_ref_param_class_root(&by_value, &llbc, no_tombstoned_leaves(), None),
            Some(owner)
        );

        // A `call_once` `tupled_args` is a hash-consed 1-tuple of `fn`.
        // The TypeDecl leaf is still `"Tuple"`; the Input class_root
        // must be the shaped `Tuple<fn(...)>` so `getitem(0)` is
        // `SomePtr` (`binaryop.py` `getitem((tup1, int2))`).
        let fn_tuple = r#"{
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [{
                    "def_id": 0,
                    "item_meta": {
                        "name": [{"Builtin": [{"Tuple": 1}, 0]}],
                        "span": {"data": {"file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}}},
                        "source_text": null,
                        "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                        "is_local": false
                    },
                    "kind": {"Struct": []}
                }, {
                    "def_id": 1,
                    "item_meta": {
                        "name": [{"Ident": ["majit_gc", 0]}, {"Ident": ["header", 0]}, {"Ident": ["GCREFOpaque", 0]}],
                        "span": {"data": {"file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}}},
                        "source_text": null,
                        "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                        "is_local": false
                    },
                    "kind": "Opaque"
                }],
                "fun_decls": [{
                    "def_id": 0,
                    "item_meta": {
                        "name": [{"Ident": ["fixture", 0]}, {"Ident": ["call_once", 0]}],
                        "span": {"data": {"file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}}},
                        "source_text": null,
                        "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                        "is_local": true
                    },
                    "signature": {
                        "is_unsafe": false,
                        "inputs": [{"Value": [3456, {"Adt": {
                            "id": 0,
                            "builtin": "Tuple",
                            "generics": {
                                "regions": [],
                                "types": [{"Value": [287, {"FnPtr": {
                                    "regions": [],
                                    "skip_binder": {
                                        "is_unsafe": false,
                                        "abi": "Rust",
                                        "is_variadic": false,
                                        "inputs": [
                                            {"Scalar": {"Integer": {"Unsigned": "U32"}}},
                                            {"Scalar": {"Integer": {"Unsigned": "Usize"}}}
                                        ],
                                        "output": {"RawPtr": [
                                            {"Adt": {"id": 1, "generics": {
                                                "regions": [], "types": [],
                                                "const_generics": [], "trait_refs": []
                                            }, "builtin": null}},
                                            "Mut"
                                        ]}
                                    }
                                }}]}],
                                "const_generics": [],
                                "trait_refs": []
                            }
                        }}]}],
                        "output": {"Scalar": "Bool"}
                    },
                    "body": "Opaque"
                }],
                "global_decls": [], "trait_decls": [], "trait_impls": []
            }
        }"#;
        let fn_llbc =
            Llbc::from_slice(fn_tuple.as_bytes()).expect("fn-pointer tuple fixture Llbc parses");
        let tupled = TyRef::Dedup { id: 3456 };
        let shaped = tyref_shaped_tuple_root(&tupled, &fn_llbc)
            .expect("dedup Tuple<fn> must have a shaped root");
        assert!(
            majit_ir::descr::is_shaped_tuple_name(&shaped),
            "shaped root must not be the bare Tuple leaf: {shaped}"
        );
        assert!(
            shaped.contains("fn("),
            "shaped root must name the fn payload: {shaped}"
        );
        assert_eq!(
            tyref_ref_param_class_root(&tupled, &fn_llbc, no_tombstoned_leaves(), None),
            Some(shaped)
        );
    }

    #[test]
    fn decode_char_literal_is_its_int_code_point() {
        let llbc = empty_llbc();
        for (lit, code) in [(">", 0x3e_i64), ("\u{0}", 0), ("\u{10ffff}", 0x10ffff)] {
            let json = serde_json::json!({ "Char": lit });
            assert!(
                matches!(decode_literal(&json), Ok(DecodedConst::Int(n)) if n == code),
                "char literal {lit:?} decodes to Int({code})",
            );
            // SwitchInt arms rtype through `AbstractUniCharRepr.convert_const`.
            assert!(
                matches!(
                    scalar_to_const_value(&json, &llbc),
                    Some(ConstValue::UniStr(ref s)) if s == lit
                ),
                "char SwitchInt arm {lit:?} is a length-1 UniStr",
            );
            let scalar = serde_json::json!({ "Scalar": { "Char": ["Char", code.to_string()] } });
            assert!(
                matches!(
                    scalar_to_const_value(&scalar, &llbc),
                    Some(ConstValue::UniStr(ref s)) if s == lit
                ),
                "Scalar Char code point {code} is a length-1 UniStr",
            );
        }
        assert!(
            decode_literal(&serde_json::json!({ "Str": ">" }))
                .is_ok_and(|c| matches!(c, DecodedConst::Str(ref s) if s == ">"))
        );
    }

    #[test]
    fn decode_scalar_i128_and_u128_preserves_full_width() {
        let signed = serde_json::json!({
            "Scalar": {
                "Signed": ["I128", i128::MIN.to_string()]
            }
        });
        assert!(matches!(
            decode_literal(&signed).expect("decode I128"),
            DecodedConst::Int128(value) if value == i128::MIN
        ));

        let unsigned = serde_json::json!({
            "Scalar": {
                "Unsigned": ["U128", u128::MAX.to_string()]
            }
        });
        assert!(matches!(
            decode_literal(&unsigned).expect("decode U128"),
            DecodedConst::UInt128(value) if value == u128::MAX
        ));

        let word = serde_json::json!({
            "Scalar": {
                "Unsigned": ["Usize", "624"]
            }
        });
        assert!(matches!(
            decode_literal(&word).expect("decode usize"),
            DecodedConst::UInt(624)
        ));
    }

    /// Loads the real interpreter LLBC to anchor fixed-array effect identity
    /// to `_random::Random::genrand32`.
    #[test]
    #[ignore]
    fn random_genrand32_fixed_array_keeps_concrete_identity() {
        use crate::model::{OpKind, ValueType};

        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real LLBC");
        let fd = llbc
            .iter_local_fns()
            .find(|fd| fd.item_meta.name_path().ends_with("::genrand32"))
            .expect("_random::Random::genrand32 in interpreter LLBC");
        let context = super::LowerContext::new(&llbc);
        let graph = super::lower_fun_decl(&context, fd).expect("lower Random::genrand32");

        let mut reads = 0usize;
        let mut writes = 0usize;
        for op in graph.blocks.iter().flat_map(|block| &block.operations) {
            match &op.kind {
                OpKind::ArrayRead {
                    item_ty,
                    array_type_id,
                    nolength,
                    ..
                } => {
                    reads += 1;
                    assert_eq!(*item_ty, ValueType::Unsigned);
                    assert_eq!(array_type_id.as_deref(), Some("[u32;624]"));
                    assert!(*nolength);
                }
                OpKind::ArrayWrite {
                    item_ty,
                    array_type_id,
                    nolength,
                    ..
                } => {
                    writes += 1;
                    assert_eq!(*item_ty, ValueType::Unsigned);
                    assert_eq!(array_type_id.as_deref(), Some("[u32;624]"));
                    assert!(*nolength);
                }
                _ => {}
            }
        }
        assert!(reads >= 1);
        assert!(writes >= 1);
    }

    /// `UnsafeCell::{new,get,get_mut}` on `RBigIntGcRoot` is the cell word.
    /// Charon spells the callee `core::cell::<Impl>::new`, and the annotator
    /// then sees `cell::UnsafeCell::new`. The lowering aliases that call to
    /// its operand, so the graph must not keep the call.
    #[test]
    fn rbigint_gc_root_unsafecell_calls_are_word_identity() {
        use crate::model::{CallTarget, OpKind};

        let path = crate::runtime_names::artifacts::MAJIT_RLIB_ULLBC;
        let llbc = Llbc::load(path).expect("load majit-rlib LLBC");
        for name in [
            "majit_rlib::rbigint::gc::<Impl>::new",
            "majit_rlib::rbigint::gc::<Impl>::set",
        ] {
            let fd = llbc
                .iter_local_fns()
                .find(|fd| fd.item_meta.name_path() == name)
                .unwrap_or_else(|| panic!("{name} in majit-rlib LLBC"));
            let context = super::LowerContext::new(&llbc);
            let graph =
                super::lower_fun_decl(&context, fd).unwrap_or_else(|e| panic!("lower {name}: {e}"));
            for op in graph.blocks.iter().flat_map(|block| &block.operations) {
                let OpKind::Call { target, .. } = &op.kind else {
                    continue;
                };
                let hit = match target {
                    CallTarget::FunctionPath { segments, .. } => {
                        segments.iter().any(|s| s.contains("UnsafeCell"))
                    }
                    CallTarget::Method { receiver_root, .. } => receiver_root
                        .as_deref()
                        .is_some_and(|root| root.contains("UnsafeCell")),
                    _ => false,
                };
                assert!(!hit, "{name} still calls {target:?}");
            }
        }
    }

    /// `live_rbigint` clones `&RBigInt` and passes the by-value result to
    /// `RBigIntGcRoot::new`. The clone's destination is the `RBigInt` ADT,
    /// which `tyref_to_value_type` paints `Ref(None)`. Without the
    /// `__cast_instance_intrinsic` narrow, `annotationoftype` never calls
    /// `getuniqueclassdef` and `SomeInstance.getattr("_digits")` sees
    /// `classdef=None`.
    #[test]
    fn live_rbigint_clone_result_is_rbigint_instance() {
        let path = crate::runtime_names::artifacts::MAJIT_RLIB_ULLBC;
        let llbc = Llbc::load(path).expect("load majit-rlib LLBC");
        let fd = llbc
            .iter_local_fns()
            .find(|fd| fd.item_meta.name_path() == "majit_rlib::rbigint::gc::live_rbigint")
            .expect("live_rbigint in majit-rlib LLBC");
        let context = super::LowerContext::new(&llbc);
        let graph = super::lower_fun_decl(&context, fd).expect("lower live_rbigint");
        let rooted = graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .any(|op| crate::model::cast_instance_root(&op.kind) == Some("RBigInt"));
        assert!(
            rooted,
            "live_rbigint clone result must be cast to RBigInt, got ops: {}",
            graph
                .blocks
                .iter()
                .flat_map(|block| &block.operations)
                .map(|op| format!("{:?}", std::mem::discriminant(&op.kind)))
                .collect::<Vec<_>>()
                .join(", ")
        );
    }

    /// `_int_bitwise_and` keeps its handles: one lives in an
    /// `Option<RBigIntGcRoot>`. `live_rbigint`'s graph returns the value, so
    /// the kept body roots it again with the real `RBigIntGcRoot::new`, which
    /// keeps the body's `acquire_owner_root` decline.
    #[test]
    fn a_kept_handle_roots_the_producer_value_with_the_real_new() {
        use crate::model::{CallTarget, LinkArg, OpKind};

        let path = crate::runtime_names::artifacts::MAJIT_RLIB_ULLBC;
        let llbc = Llbc::load(path).expect("load majit-rlib LLBC");
        let fd = llbc
            .iter_local_fns()
            .find(|fd| fd.item_meta.name_path() == "majit_rlib::rbigint::_int_bitwise_and")
            .expect("_int_bitwise_and in majit-rlib LLBC");
        let context = super::LowerContext::new(&llbc);
        let graph = super::lower_fun_decl(&context, fd).expect("lower _int_bitwise_and");
        let leaf_of = |op: &crate::model::SpaceOperation| match &op.kind {
            OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                ..
            } => segments.last().cloned(),
            _ => None,
        };
        let rerooted = graph.blocks.iter().any(|block| {
            let ops = &block.operations;
            ops.iter().enumerate().any(|(i, op)| {
                leaf_of(op).as_deref() == Some("live_rbigint")
                    && ops[i + 1..].iter().any(|later| {
                        let OpKind::Call {
                            target: CallTarget::FunctionPath { segments, .. },
                            args,
                            ..
                        } = &later.kind
                        else {
                            return false;
                        };
                        segments.iter().any(|s| s == "RBigIntGcRoot")
                            && segments.last().is_some_and(|leaf| leaf == "new")
                            && args.len() == 1
                            && matches!(&args[0], LinkArg::Value(_))
                    })
            })
        });
        assert!(
            rerooted,
            "live_rbigint's value is not rooted again by RBigIntGcRoot::new"
        );
        // The `bool::then` closure keeps its handle and returns it; the kept
        // caller stores it in the `Option<RBigIntGcRoot>` as a handle.
        let closure = llbc
            .iter_local_fns()
            .find(|fd| {
                fd.item_meta.name_path()
                    == "majit_rlib::rbigint::_int_bitwise_and::<Impl>::call_once"
            })
            .expect("_int_bitwise_and closure in majit-rlib LLBC");
        super::lower_fun_decl(&context, closure).expect("lower the _int_bitwise_and closure");
    }

    /// `live_rbigint` clones and roots the clone. Its handle only leaves
    /// through the return place, so the graph returns the clone itself and
    /// never enters `RBigIntGcRoot::new`, whose `acquire_owner_root` has no
    /// JIT counterpart.
    #[test]
    fn live_rbigint_returns_the_rooted_value() {
        use crate::model::{CallTarget, OpKind};

        let path = crate::runtime_names::artifacts::MAJIT_RLIB_ULLBC;
        let llbc = Llbc::load(path).expect("load majit-rlib LLBC");
        let fd = llbc
            .iter_local_fns()
            .find(|fd| fd.item_meta.name_path() == "majit_rlib::rbigint::gc::live_rbigint")
            .expect("live_rbigint in majit-rlib LLBC");
        let context = super::LowerContext::new(&llbc);
        let graph = super::lower_fun_decl(&context, fd).expect("lower live_rbigint");
        for op in graph.blocks.iter().flat_map(|block| &block.operations) {
            let OpKind::Call { target, .. } = &op.kind else {
                continue;
            };
            let names_handle = match target {
                CallTarget::FunctionPath { segments, .. } => segments
                    .iter()
                    .any(|s| s.contains("RBigIntGcRoot") || s.contains("owner_root")),
                CallTarget::Method { receiver_root, .. } => receiver_root
                    .as_deref()
                    .is_some_and(|root| root.contains("RBigIntGcRoot")),
                _ => false,
            };
            assert!(!names_handle, "live_rbigint still calls {target:?}");
        }
    }

    /// Lower one `pyre_object` function by its full `name_path`.
    fn lower_object_fn(name_path: &str) -> crate::model::FunctionGraph {
        let path = crate::runtime_names::artifacts::OBJECT_ULLBC;
        let llbc = Llbc::load(path).expect("load pyre-object LLBC");
        let fd = llbc
            .iter_local_fns()
            .find(|fd| fd.item_meta.name_path() == name_path)
            .unwrap_or_else(|| panic!("{name_path} in pyre-object LLBC"));
        let context = super::LowerContext::new(&llbc);
        super::lower_fun_decl(&context, fd)
            .unwrap_or_else(|err| panic!("lower {name_path}: {err:?}"))
    }

    fn calls_leaf(graph: &crate::model::FunctionGraph, leaf: &str) -> bool {
        use crate::model::{CallTarget, OpKind};
        graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .any(|op| match &op.kind {
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } => segments.last().is_some_and(|s| s == leaf),
                OpKind::Call {
                    target: CallTarget::Method { name, .. },
                    ..
                } => name == leaf,
                _ => false,
            })
    }

    /// Jitcode is produced before the GC transform, so no lowered graph reads
    /// the header flag word: `dict_write_barrier`'s `GcHeader::has_flag` stays
    /// the call it is in the source.
    #[test]
    fn dict_write_barrier_does_not_lower_the_header_flag_test() {
        use crate::model::OpKind;
        let graph = lower_object_fn("pyre_object::dictmultiobject::dict_write_barrier");
        for op in graph.blocks.iter().flat_map(|block| &block.operations) {
            if let OpKind::FieldRead { field, .. } = &op.kind {
                assert_ne!(
                    field.name, "tid_and_flags",
                    "dict_write_barrier reads the GC header flag word"
                );
            }
        }
    }

    /// `w_type_set_w_doc` is `type_write_barrier(obj); t.w_doc = w_doc`.
    /// The barrier call is dropped and the `setfield` stays; the backend
    /// rewrite puts `COND_CALL_GC_WB` in front of it.
    #[test]
    fn type_write_barrier_call_leaves_only_the_setfield() {
        use crate::model::OpKind;
        let graph = lower_object_fn("pyre_object::typeobject::w_type_set_w_doc");
        assert!(
            !calls_leaf(&graph, "type_write_barrier"),
            "w_type_set_w_doc still calls type_write_barrier"
        );
        assert!(
            graph.blocks.iter().flat_map(|block| &block.operations).any(
                |op| matches!(&op.kind, OpKind::FieldWrite { field, .. } if field.name == "w_doc")
            ),
            "w_type_set_w_doc lost its w_doc setfield"
        );
    }

    /// `write_cell`'s in-place `ObjectMutableCell` arm is
    /// `try_gc_write_barrier_prebuilt(cell); cell.w_value = w_value`. It does
    /// not call `try_gc_owns_object` itself. jtransform
    /// `drop_guarded_gc_write_barriers` drops that `gc_hook` barrier
    /// when the store follows, so rewrite can put `COND_CALL_GC_WB` on
    /// the `setfield_gc`.
    #[test]
    fn write_cell_calls_try_gc_write_barrier_prebuilt_before_w_value_setfield() {
        use crate::model::{CallTarget, OpKind};
        let graph = lower_object_fn("pyre_object::celldict::write_cell");
        assert!(
            !calls_leaf(&graph, "try_gc_owns_object"),
            "write_cell still calls try_gc_owns_object"
        );
        let is_barrier = |kind: &OpKind| {
            matches!(
                kind,
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } if segments.last().is_some_and(|s| s == "try_gc_write_barrier_prebuilt")
            )
        };
        let is_store = |kind: &OpKind| matches!(kind, OpKind::FieldWrite { field, .. } if field.name == "w_value");
        let mut barrier_before_store = false;
        for block in &graph.blocks {
            let mut saw_barrier = false;
            for op in &block.operations {
                if is_barrier(&op.kind) {
                    saw_barrier = true;
                }
                if saw_barrier && is_store(&op.kind) {
                    barrier_before_store = true;
                }
            }
            if saw_barrier {
                for succ in graph.successors(block.id) {
                    if graph.blocks[succ.0]
                        .operations
                        .iter()
                        .any(|op| is_store(&op.kind))
                    {
                        barrier_before_store = true;
                    }
                }
            }
        }
        assert!(
            barrier_before_store,
            "write_cell's try_gc_write_barrier_prebuilt does not precede the w_value setfield"
        );
    }

    /// `ll_list_obj_capacity` is `len(l.items)` (`rlist.py`
    /// `_ll_list_resize_hint` `allocated = len(l.items)`). The resizable
    /// `ItemsBlock` may be NULL; `items_block_capacity` returns 0 for
    /// NULL, so the call stays. PyPy's `ll_newemptylist` allocates a
    /// zero-length array, which pyre does not have yet.
    #[test]
    fn items_block_capacity_on_a_resizable_list_stays_a_call() {
        use crate::model::OpKind;
        let graph = lower_object_fn("pyre_object::listobject::ll_list_obj_capacity");
        assert!(
            calls_leaf(&graph, "items_block_capacity"),
            "ll_list_obj_capacity must keep items_block_capacity"
        );
        let has_arraylen = graph.blocks.iter().any(|block| {
            block
                .operations
                .iter()
                .any(|op| matches!(&op.kind, OpKind::ArrayLen { .. }))
        });
        assert!(!has_arraylen, "the items header is not ll_fixed_length");
    }

    /// `ll_list_obj_setitem_fast` is `items_block_set_ref(l.items, index,
    /// item)`. The call becomes the one `setarrayitem_gc` on the object
    /// items array, the same collapse `FixedObjectArray::set_ref` gets.
    /// The ArrayWrite base is the object-strategy unerase of the
    /// `ItemsBlock` (`rerased.py` / `ListStrategy.unerase`).
    #[test]
    fn items_block_set_ref_call_is_one_array_write() {
        use crate::model::OpKind;
        let graph = lower_object_fn("pyre_object::listobject::ll_list_obj_setitem_fast");
        assert!(
            !calls_leaf(&graph, "items_block_set_ref"),
            "ll_list_obj_setitem_fast still calls items_block_set_ref"
        );
        let mut writes = Vec::new();
        let mut object_items_casts = Vec::new();
        for op in graph.blocks.iter().flat_map(|block| &block.operations) {
            if crate::model::cast_instance_root(&op.kind) == Some("[PyObject]") {
                if let Some(result) = op.result.as_ref() {
                    object_items_casts.push(result.clone());
                }
            }
            if let OpKind::ArrayWrite {
                base,
                item_ty,
                array_type_id,
                ..
            } = &op.kind
            {
                writes.push((base.clone(), item_ty.clone(), array_type_id.clone()));
            }
        }
        assert_eq!(
            writes
                .iter()
                .map(|(_, item_ty, array_type_id)| (item_ty.clone(), array_type_id.clone()))
                .collect::<Vec<_>>(),
            vec![(
                crate::model::ValueType::Ref(None),
                Some(super::OBJECT_REF_GCARRAY_TYPE_ID.to_string())
            )],
            "expected one object-array setarrayitem"
        );
        assert!(
            object_items_casts.contains(&writes[0].0),
            "ArrayWrite base must be the [PyObject] unerase of the ItemsBlock"
        );
    }

    /// `roots[i] = GcRef(digits as usize)` must store `Ptr(GCREF)`, the
    /// same word as `GcRef::NULL` (`ConstRefNull`). The transparent
    /// `usize` field would otherwise store `Integer` and
    /// `listdef.generalize` refuses `Ptr(GCREF) ∪ Integer`.
    #[test]
    fn gcref_address_cast_store_keeps_gcref_pointer() {
        use crate::model::OpKind;

        let path = crate::runtime_names::artifacts::MAJIT_RLIB_ULLBC;
        let llbc = Llbc::load(path).expect("load majit-rlib LLBC");
        let fd = llbc
            .iter_local_fns()
            .find(|fd| {
                fd.item_meta.name_path()
                    == "majit_rlib::rbigint::<Impl>::with_size_reloading_digits"
            })
            .expect("with_size_reloading_digits");
        let context = super::LowerContext::new(&llbc);
        let graph = super::lower_fun_decl(&context, fd).expect("lower with_size_reloading_digits");
        let mut gcref_casts = 0;
        let mut pointer_stores = 0;
        for op in graph.blocks.iter().flat_map(|block| &block.operations) {
            if crate::model::cast_instance_root(&op.kind) == Some("GCREF") {
                gcref_casts += 1;
            }
            if let OpKind::ArrayWrite {
                item_ty: crate::model::ValueType::Ref(_),
                ..
            } = &op.kind
            {
                pointer_stores += 1;
            }
        }
        assert!(
            gcref_casts >= 2,
            "address-cast GcRef construction must retype to GCREF, casts={gcref_casts}"
        );
        assert!(
            pointer_stores >= 2,
            "GcRef list stores must be pointer words, pointer_stores={pointer_stores}"
        );
    }

    /// `W_Random::rnd` is `Random::from_obj(self.rnd).expect(...)`.
    /// The `Option<&mut Random>` consumer must lower to the niche guard;
    /// a residual `expect` method is `getattr("expect")` on the instance.
    #[test]
    fn random_rnd_expect_is_niche_guard() {
        use crate::model::{CallTarget, OpKind};

        // `_random` lives in `pyre-module`, so its graphs are in that artefact.
        let path = crate::runtime_names::artifacts::MODULE_ULLBC;
        let llbc = Llbc::load(path).expect("load pyre-module LLBC");
        let fd = llbc
            .iter_local_fns()
            .find(|fd| fd.item_meta.name_path() == "pyre_module::module::_random::<Impl>::rnd")
            .expect("W_Random::rnd");
        let context = super::LowerContext::new(&llbc);
        let graph = super::lower_fun_decl(&context, fd).expect("lower rnd");
        for op in graph.blocks.iter().flat_map(|block| &block.operations) {
            if let OpKind::Call {
                target: CallTarget::Method { name, .. },
                ..
            } = &op.kind
            {
                assert_ne!(name.as_str(), "expect", "rnd still calls expect");
            }
        }
        // `remove_assertion_errors` drops the never-None arm and its `ne`,
        // leaving the niche `null_mut` the guard compared against.
        let saw_null = graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .any(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call {
                        target: CallTarget::FunctionPath { segments, .. },
                        ..
                    } if segments.as_slice() == ["core", "ptr", "null_mut"]
                )
            });
        assert!(saw_null, "niche Option::expect must build a null pointer");
    }

