    #[test]
    fn named_const_merge_restarts_when_a_crate_repeats() {
        use super::OpKind;
        let one = |path: &str, v: u64| {
            let mut m = std::collections::HashMap::new();
            m.insert(path.to_string(), OpKind::ConstUInt(v));
            m
        };
        // A fresh table for this test, restored when the guard drops.
        let _guard = super::push_named_const_folds(std::collections::HashMap::new());
        super::merge_named_const_folds("pyre_object", one("pyre_object::A", 1));
        super::merge_named_const_folds("pyre_interpreter", one("pyre_interpreter::B", 2));
        assert!(super::named_const_fold_for_path("pyre_object::A").is_some());
        assert!(super::named_const_fold_for_path("pyre_interpreter::B").is_some());
        // `pyre_object` again means a second invocation started: the
        // earlier invocation's entries must not survive into it.
        super::merge_named_const_folds("pyre_object", one("pyre_object::A", 1));
        assert!(super::named_const_fold_for_path("pyre_object::A").is_some());
        assert!(super::named_const_fold_for_path("pyre_interpreter::B").is_none());
    }

    #[test]
    fn const_eval_binop_declines_width_and_sign_ambiguous_folds() {
        use super::{ConstLit, const_eval_binop};
        use serde_json::json;

        // Wrapping Add/Sub/Mul: the i64 carrier has no operand width, so
        // `255u8 + 1` (wraps to 0, not 256) must residualize.
        assert!(
            const_eval_binop(
                &json!({ "Add": "Wrap" }),
                ConstLit::Int(255),
                ConstLit::Int(1)
            )
            .is_none()
        );
        assert!(
            const_eval_binop(
                &json!({ "Sub": "Wrap" }),
                ConstLit::Int(0),
                ConstLit::Int(1)
            )
            .is_none()
        );
        assert!(
            const_eval_binop(
                &json!({ "Mul": "Wrap" }),
                ConstLit::Int(16),
                ConstLit::Int(16)
            )
            .is_none()
        );
        // Non-wrapping (panic-checked) forms still fold: a valid const
        // initializer never overflows, so checked_* is exact.
        assert!(matches!(
            const_eval_binop(
                &json!({ "Add": "Panic" }),
                ConstLit::Int(255),
                ConstLit::Int(1)
            ),
            Some(ConstLit::Int(256))
        ));

        // Right shift with a negative carrier is signedness-ambiguous
        // (`u64::MAX >> 1` collapsed to `-1 >> 1`) — decline.
        assert!(
            const_eval_binop(
                &json!({ "Shr": "Wrap" }),
                ConstLit::Int(-1),
                ConstLit::Int(1)
            )
            .is_none()
        );
        // A non-negative left operand shifts identically signed/unsigned.
        assert!(matches!(
            const_eval_binop(
                &json!({ "Shr": "Wrap" }),
                ConstLit::Int(0x7fff_ffff),
                ConstLit::Int(1)
            ),
            Some(ConstLit::Int(0x3fff_ffff))
        ));

        // Census fold targets survive: SMALL_MAX = `(1i64<<62)-1` builds
        // from a Shl and a SubChecked; SMALL_MIN negates the same Shl.
        assert!(matches!(
            const_eval_binop(&json!({ "Shl": "Panic" }), ConstLit::Int(1), ConstLit::Int(62)),
            Some(ConstLit::Int(v)) if v == 1i64 << 62
        ));
        assert!(matches!(
            const_eval_binop(&json!("SubChecked"), ConstLit::Int(1i64 << 62), ConstLit::Int(1)),
            Some(ConstLit::Checked(v, false)) if v == (1i64 << 62) - 1
        ));
        assert!(matches!(
            const_eval_binop(&json!("AddChecked"), ConstLit::Int(1i64 << 62), ConstLit::Int(1)),
            Some(ConstLit::Checked(v, false)) if v == (1i64 << 62) + 1
        ));
    }

    /// `pub const MEMBER_DIRECT_FLAG: u32 = 1 << 31` (typedef.rs) records a
    /// mixed-signedness pair, because an unsuffixed shift amount defaults to
    /// `i32` while the shifted value is `u32`.  Charon plants the
    /// shift-overflow assert (`31i32 as u32 < 32u32`) ahead of it, which is a
    /// mixed pair too, so both halves have to fold or the const falls through
    /// to a residual accessor call no registry can bind.
    #[test]
    fn const_eval_binop_folds_mixed_signedness_shifts_and_comparisons() {
        use super::{ConstLit, const_eval_binop};
        use serde_json::json;

        // The shift itself: `1u32 << 31i32`.
        assert!(matches!(
            const_eval_binop(
                &json!({ "Shl": "Wrap" }),
                ConstLit::UInt(1),
                ConstLit::Int(31)
            ),
            Some(ConstLit::UInt(v)) if v == 1u64 << 31
        ));
        // The overflow assert's comparison: `31u32 < 32u32` reached with the
        // cast's signedness dropped into the `Int` carrier.
        assert!(matches!(
            const_eval_binop(&json!("Lt"), ConstLit::Int(31), ConstLit::UInt(32)),
            Some(ConstLit::Bool(true))
        ));
        assert!(matches!(
            const_eval_binop(&json!("Ge"), ConstLit::UInt(32), ConstLit::Int(31)),
            Some(ConstLit::Bool(true))
        ));

        // A negative signed side makes the two carriers disagree on the
        // value — stay declined, as the `Shr` sign guard already does.
        assert!(
            const_eval_binop(
                &json!({ "Shl": "Wrap" }),
                ConstLit::UInt(1),
                ConstLit::Int(-1)
            )
            .is_none()
        );
        assert!(const_eval_binop(&json!("Lt"), ConstLit::Int(-1), ConstLit::UInt(0)).is_none());

        // Mixed arithmetic stays declined: the pair leaves the result *type*
        // undetermined, and Rust needs an explicit cast to write it at all.
        assert!(
            const_eval_binop(
                &json!({ "Add": "Panic" }),
                ConstLit::UInt(1),
                ConstLit::Int(1)
            )
            .is_none()
        );
    }

    /// A `Shl` folded at the 64-bit carrier can be wider than the local it is
    /// assigned to — Rust does not treat shifted-out bits as an overflow, so
    /// `200u8 << 1` is a legal const equal to 144, not 400.  rustc truncates
    /// to the destination type and so must the fold.
    /// `test_flatten.py test_force_cast_ints` on a 64-bit word.
    #[test]
    fn int_to_int_cast_follows_the_force_cast_table() {
        use super::{IntToIntCast, int_to_int_cast};
        const SCHAR: (u64, bool) = (1, false);
        const UCHAR: (u64, bool) = (1, true);
        const SHORT: (u64, bool) = (2, false);
        const USHORT: (u64, bool) = (2, true);
        const LONG: (u64, bool) = (8, false);
        const ULONG: (u64, bool) = (8, true);
        let noop = Some(IntToIntCast::Noop);
        let and = |m| Some(IntToIntCast::And(m));
        let signext = |n| Some(IntToIntCast::Signext(n));
        for (from, to, expected) in [
            (SCHAR, SCHAR, noop.clone()),
            (SCHAR, UCHAR, and(255)),
            (SCHAR, SHORT, noop.clone()),
            (SCHAR, USHORT, and(65535)),
            (SCHAR, LONG, noop.clone()),
            (SCHAR, ULONG, noop.clone()),
            (UCHAR, SCHAR, signext(1)),
            (UCHAR, UCHAR, noop.clone()),
            (UCHAR, SHORT, noop.clone()),
            (UCHAR, USHORT, noop.clone()),
            (UCHAR, LONG, noop.clone()),
            (UCHAR, ULONG, noop.clone()),
            (SHORT, SCHAR, signext(1)),
            (SHORT, UCHAR, and(255)),
            (SHORT, SHORT, noop.clone()),
            (SHORT, USHORT, and(65535)),
            (SHORT, LONG, noop.clone()),
            (SHORT, ULONG, noop.clone()),
            (USHORT, SCHAR, signext(1)),
            (USHORT, UCHAR, and(255)),
            (USHORT, SHORT, signext(2)),
            (USHORT, USHORT, noop.clone()),
            (USHORT, LONG, noop.clone()),
            (USHORT, ULONG, noop.clone()),
            (LONG, SCHAR, signext(1)),
            (LONG, UCHAR, and(255)),
            (LONG, SHORT, signext(2)),
            (LONG, USHORT, and(65535)),
            (LONG, LONG, noop.clone()),
            (LONG, ULONG, noop.clone()),
            (ULONG, SCHAR, signext(1)),
            (ULONG, UCHAR, and(255)),
            (ULONG, SHORT, signext(2)),
            (ULONG, USHORT, and(65535)),
            (ULONG, LONG, noop.clone()),
            (ULONG, ULONG, noop.clone()),
            // 32-bit halves: `i64 as u32` masks, `i64 as i32` re-extends.
            (LONG, (4, true), and(0xffff_ffff)),
            (LONG, (4, false), signext(4)),
            ((4, false), (4, true), and(0xffff_ffff)),
        ] {
            assert_eq!(int_to_int_cast(from, to, 8), expected, "{from:?} -> {to:?}");
        }
        // A 128-bit operand is the longlong leg, not covered here.
        assert_eq!(int_to_int_cast((16, false), UCHAR, 8), None);
    }

    #[test]
    fn const_narrow_to_target_truncates_to_the_destination_width() {
        use super::{ConstLit, const_narrow_to_target};
        use serde_json::json;

        let u8_ty = json!({ "Integer": { "Unsigned": "U8" } });
        assert!(matches!(
            const_narrow_to_target(Some(&u8_ty), ConstLit::UInt(400)),
            ConstLit::UInt(144)
        ));
        // A signed destination re-extends rather than masking.
        let i8_ty = json!({ "Integer": { "Signed": "I8" } });
        assert!(matches!(
            const_narrow_to_target(Some(&i8_ty), ConstLit::UInt(200)),
            ConstLit::Int(-56)
        ));
        // The u32 flag itself is already in range and must survive intact.
        let u32_ty = json!({ "Integer": { "Unsigned": "U32" } });
        assert!(matches!(
            const_narrow_to_target(Some(&u32_ty), ConstLit::UInt(1 << 31)),
            ConstLit::UInt(v) if v == 1u64 << 31
        ));
        // Non-integer and absent destinations pass the value through.
        assert!(matches!(
            const_narrow_to_target(None, ConstLit::Int(7)),
            ConstLit::Int(7)
        ));
        let bool_ty = json!({ "Bool": [] });
        assert!(matches!(
            const_narrow_to_target(Some(&bool_ty), ConstLit::Bool(true)),
            ConstLit::Bool(true)
        ));
    }

    #[test]
    fn resolve_to_producer_op_follows_cross_block_inputarg_link() {
        use super::resolve_to_producer_op;
        use crate::flowspace::model::Variable;
        use crate::model::{FunctionGraph, Link, OpKind, SpaceOperation};

        let mut graph = FunctionGraph::new("xblock");
        let a = graph.create_block();
        let b = graph.create_block();

        // block A produces `x` via a ConstInt op.
        let x = Variable::new();
        graph.block_mut(a).operations.push(SpaceOperation {
            result: Some(x.clone()),
            kind: OpKind::ConstInt(7),
        });

        // block B takes `w` as its single inputarg; A links to B passing
        // `x` for `w` (the cross-block threading the recognizer sees).
        let w = Variable::new();
        graph.block_mut(b).inputargs = vec![w.clone()];
        let link = Link::from_variables(&graph, vec![x.clone()], b, None).with_prevblock(a);
        graph.block_mut(a).exits = vec![link];

        // `w` (block B inputarg) back-traces to A's ConstInt op.
        assert_eq!(resolve_to_producer_op(&graph, &w), Some((a, 0)));
        // A direct op result resolves to itself.
        assert_eq!(resolve_to_producer_op(&graph, &x), Some((a, 0)));
        // An unrelated free Variable has no producer.
        assert_eq!(resolve_to_producer_op(&graph, &Variable::new()), None);
    }

    fn vec_alloc_and_set_r(result: Variable) -> SpaceOperation {
        use majit_ir::rvec::{VecItemKind, VecOp, vec_helper_path};
        SpaceOperation {
            result: Some(result),
            kind: OpKind::Call {
                target: CallTarget::function_path(
                    vec_helper_path(VecOp::AllocAndSet, VecItemKind::Ref).split("::"),
                ),
                args: crate::model::call_args(vec![Variable::new(), Variable::new()]),
                result_ty: ValueType::Int,
            },
        }
    }

    fn vec_call_result(result: Variable, leaf: &str) -> SpaceOperation {
        SpaceOperation {
            result: Some(result),
            kind: OpKind::Call {
                target: CallTarget::function_path(["other", leaf]),
                args: vec![],
                result_ty: ValueType::Int,
            },
        }
    }

    fn graph_call_leaves(graph: &FunctionGraph) -> Vec<String> {
        graph
            .blocks
            .iter()
            .flat_map(|b| &b.operations)
            .filter_map(|op| match &op.kind {
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } => segments.last().cloned(),
                _ => None,
            })
            .collect()
    }

    /// `rewrite_op_free` frees a header that reached the drop through a
    /// return/unwind phi: both incoming Links carry the same in-graph
    /// `ll_vec_alloc_and_set` result, so the drop emits `ll_vec_free`.
    #[test]
    fn rust_vec_drop_frees_phi_merged_header() {
        use super::{emit_rust_vec_drop_if_allocated, rust_vec_header_allocated_in_graph};
        use crate::model::Link;
        use majit_ir::rvec::VecItemKind;

        let mut graph = FunctionGraph::new("phi_vec_drop");
        let alloc_bb = graph.create_block();
        let ok_bb = graph.create_block();
        let err_bb = graph.create_block();
        let drop_bb = graph.create_block();

        let allocated = Variable::new();
        graph
            .block_mut(alloc_bb)
            .operations
            .push(vec_alloc_and_set_r(allocated.clone()));

        let ok_h = Variable::new();
        graph.block_mut(ok_bb).inputargs = vec![ok_h.clone()];
        let err_h = Variable::new();
        graph.block_mut(err_bb).inputargs = vec![err_h.clone()];
        let drop_h = Variable::new();
        graph.block_mut(drop_bb).inputargs = vec![drop_h.clone()];

        graph.block_mut(alloc_bb).exits = vec![
            Link::from_variables(&graph, vec![allocated.clone()], ok_bb, None)
                .with_prevblock(alloc_bb),
            Link::from_variables(&graph, vec![allocated.clone()], err_bb, None)
                .with_prevblock(alloc_bb),
        ];
        graph.block_mut(ok_bb).exits = vec![
            Link::from_variables(&graph, vec![ok_h.clone()], drop_bb, None).with_prevblock(ok_bb),
        ];
        graph.block_mut(err_bb).exits = vec![
            Link::from_variables(&graph, vec![err_h.clone()], drop_bb, None).with_prevblock(err_bb),
        ];

        // The drop header is a two-predecessor phi: `resolve_to_producer_op`
        // has no single producer, which is the leak the SSA walk closes.
        assert_eq!(super::resolve_to_producer_op(&graph, &drop_h), None);
        assert!(rust_vec_header_allocated_in_graph(&graph, &drop_h));
        assert!(emit_rust_vec_drop_if_allocated(
            &mut graph,
            drop_bb,
            &drop_h,
            VecItemKind::Ref,
        ));
        let leaves = graph_call_leaves(&graph);
        assert!(
            leaves.iter().any(|leaf| leaf == "ll_vec_free_r"),
            "phi-merged in-graph header must be freed: {leaves:?}"
        );
    }

    /// A header that is only a call result in this graph is not this
    /// graph's `raw_malloc` allocation; `rewrite_op_free` of it would
    /// free a pointer another graph (or a residual) owns.
    #[test]
    fn rust_vec_drop_does_not_free_call_result_header() {
        use super::{emit_rust_vec_drop_if_allocated, rust_vec_header_allocated_in_graph};
        use crate::model::Link;
        use majit_ir::rvec::VecItemKind;

        let mut graph = FunctionGraph::new("call_result_vec_drop");
        let call_bb = graph.create_block();
        let drop_bb = graph.create_block();

        let returned = Variable::new();
        graph
            .block_mut(call_bb)
            .operations
            .push(vec_call_result(returned.clone(), "returns_vec"));

        let drop_h = Variable::new();
        graph.block_mut(drop_bb).inputargs = vec![drop_h.clone()];
        graph.block_mut(call_bb).exits = vec![
            Link::from_variables(&graph, vec![returned.clone()], drop_bb, None)
                .with_prevblock(call_bb),
        ];

        assert!(!rust_vec_header_allocated_in_graph(&graph, &drop_h));
        assert!(!rust_vec_header_allocated_in_graph(&graph, &returned));
        assert!(!emit_rust_vec_drop_if_allocated(
            &mut graph,
            drop_bb,
            &drop_h,
            VecItemKind::Ref,
        ));
        let leaves = graph_call_leaves(&graph);
        assert!(
            !leaves.iter().any(|leaf| leaf.starts_with("ll_vec_free")),
            "call-result header must not be freed by this graph: {leaves:?}"
        );
    }

    /// A phi that mixes an in-graph alloc with a call result cannot prove
    /// ownership of the live header.
    #[test]
    fn rust_vec_drop_does_not_free_mixed_phi_header() {
        use super::{emit_rust_vec_drop_if_allocated, rust_vec_header_allocated_in_graph};
        use crate::model::Link;
        use majit_ir::rvec::VecItemKind;

        let mut graph = FunctionGraph::new("mixed_phi_vec_drop");
        let alloc_bb = graph.create_block();
        let call_bb = graph.create_block();
        let drop_bb = graph.create_block();

        let allocated = Variable::new();
        graph
            .block_mut(alloc_bb)
            .operations
            .push(vec_alloc_and_set_r(allocated.clone()));
        let returned = Variable::new();
        graph
            .block_mut(call_bb)
            .operations
            .push(vec_call_result(returned.clone(), "returns_vec"));

        let drop_h = Variable::new();
        graph.block_mut(drop_bb).inputargs = vec![drop_h.clone()];
        graph.block_mut(alloc_bb).exits = vec![
            Link::from_variables(&graph, vec![allocated.clone()], drop_bb, None)
                .with_prevblock(alloc_bb),
        ];
        graph.block_mut(call_bb).exits = vec![
            Link::from_variables(&graph, vec![returned.clone()], drop_bb, None)
                .with_prevblock(call_bb),
        ];

        assert!(!rust_vec_header_allocated_in_graph(&graph, &drop_h));
        assert!(!emit_rust_vec_drop_if_allocated(
            &mut graph,
            drop_bb,
            &drop_h,
            VecItemKind::Ref,
        ));
        let leaves = graph_call_leaves(&graph);
        assert!(
            !leaves.iter().any(|leaf| leaf.starts_with("ll_vec_free")),
            "mixed phi must not free: {leaves:?}"
        );
    }

    fn owned_vec_drop_llbc(
        name: &str,
        arg_count: u64,
        locals: Vec<serde_json::Value>,
        blocks: Vec<serde_json::Value>,
        extra_types: Vec<serde_json::Value>,
        extra_funs: Vec<serde_json::Value>,
    ) -> Llbc {
        let span = || {
            serde_json::json!({
                "data": {
                    "file_id": 0,
                    "beg": {"line": 1, "col": 0},
                    "end": {"line": 1, "col": 1}
                }
            })
        };
        let item_meta = |path: &[&str], is_local: bool| {
            serde_json::json!({
                "name": path.iter().map(|segment| {
                    if *segment == "<Impl>" {
                        serde_json::json!({"Impl": {"kind": "InherentImplBlock"}})
                    } else {
                        serde_json::json!({"Ident": [segment, 0]})
                    }
                }).collect::<Vec<_>>(),
                "span": span(),
                "source_text": null,
                "attr_info": {
                    "attributes": [],
                    "inline": null,
                    "rename": null,
                    "public": true
                },
                "is_local": is_local
            })
        };
        let i64_ty = serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}});
        let vec_ty = serde_json::json!({
            "Adt": {
                "id": 0,
                "generics": {
                    "regions": [],
                    "types": [i64_ty],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        });
        let unit = serde_json::json!({
            "Adt": {
                "id": 0,
                "builtin": "Tuple",
                "generics": {
                    "regions": [],
                    "types": [],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        });
        let inputs: Vec<serde_json::Value> = locals
            .iter()
            .skip(1)
            .take(arg_count as usize)
            .filter_map(|local| local.get("ty").cloned())
            .collect();
        let subject = serde_json::json!({
            "def_id": 0,
            "item_meta": item_meta(&["fixture", name], true),
            "signature": {
                "is_unsafe": false,
                "inputs": inputs,
                "output": unit.clone()
            },
            "body": {
                "Unstructured": {
                    "span": span(),
                    "locals": {"arg_count": arg_count, "locals": locals},
                    "body": blocks
                }
            }
        });
        let vec_new = serde_json::json!({
            "def_id": 1,
            "item_meta": item_meta(&["alloc", "vec", "<Impl>", "new"], false),
            "signature": {
                "is_unsafe": false,
                "inputs": [],
                "output": vec_ty.clone()
            },
            "body": "Opaque"
        });
        let sink = serde_json::json!({
            "def_id": 2,
            "item_meta": item_meta(&["fixture", "sink"], false),
            "signature": {
                "is_unsafe": false,
                "inputs": [vec_ty],
                "output": unit
            },
            "body": "Opaque"
        });
        let vec_decl = serde_json::json!({
            "def_id": 0,
            "item_meta": item_meta(&["alloc", "vec", "Vec"], false),
            "kind": {"Struct": []}
        });
        let mut types = vec![vec_decl];
        types.extend(extra_types);
        let mut funs = vec![subject, vec_new, sink];
        funs.extend(extra_funs);
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": types,
                "fun_decls": funs,
                "global_decls": [],
                "trait_decls": [],
                "trait_impls": []
            }
        });
        Llbc::from_slice(file.to_string().as_bytes()).expect("owned vec drop fixture parses")
    }

    fn owned_vec_ty() -> serde_json::Value {
        serde_json::json!({
            "Adt": {
                "id": 0,
                "generics": {
                    "regions": [],
                    "types": [{"Scalar": {"Integer": {"Signed": "I64"}}}],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        })
    }

    fn owned_vec_unit_ty() -> serde_json::Value {
        serde_json::json!({
            "Adt": {
                "id": 0,
                "builtin": "Tuple",
                "generics": {
                    "regions": [],
                    "types": [],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        })
    }

    fn owned_vec_span() -> serde_json::Value {
        serde_json::json!({
            "data": {
                "file_id": 0,
                "beg": {"line": 1, "col": 0},
                "end": {"line": 1, "col": 1}
            }
        })
    }

    fn owned_vec_local(index: u64, ty: &serde_json::Value) -> serde_json::Value {
        serde_json::json!({
            "index": index,
            "name": null,
            "span": owned_vec_span(),
            "ty": ty
        })
    }

    fn owned_vec_place(index: u64, ty: &serde_json::Value) -> serde_json::Value {
        serde_json::json!({"kind": {"Local": index}, "ty": ty})
    }

    fn owned_vec_block(
        statements: Vec<serde_json::Value>,
        terminator: serde_json::Value,
    ) -> serde_json::Value {
        serde_json::json!({
            "statements": statements,
            "terminator": {"span": owned_vec_span(), "kind": terminator}
        })
    }

    fn owned_vec_new_call(
        dest: u64,
        dest_ty: &serde_json::Value,
        target: u64,
        unwind: u64,
    ) -> serde_json::Value {
        serde_json::json!({"Call": {
            "call": {
                "func": {"Regular": {
                    "kind": {"Fun": 1},
                    "generics": {
                        "regions": [],
                        "types": [],
                        "const_generics": [],
                        "trait_refs": []
                    }
                }},
                "args": [],
                "dest": owned_vec_place(dest, dest_ty)
            },
            "target": target,
            "on_unwind": unwind
        }})
    }

    fn owned_vec_drop(
        local: u64,
        ty: &serde_json::Value,
        target: u64,
        unwind: u64,
    ) -> serde_json::Value {
        serde_json::json!({"Drop": {
            "place": owned_vec_place(local, ty),
            "fn_ptr": {"kind": {"Fun": 1}, "generics": {}},
            "target": target,
            "on_unwind": unwind
        }})
    }

    fn owned_vec_return_unit(unit: &serde_json::Value) -> serde_json::Value {
        owned_vec_block(
            vec![serde_json::json!({
                "span": owned_vec_span(),
                "kind": {"Assign": [
                    owned_vec_place(0, unit),
                    {"Aggregate": ["Tuple", []]}
                ]}
            })],
            serde_json::json!("Return"),
        )
    }

    fn owned_vec_leaves(graph: &FunctionGraph) -> Vec<String> {
        graph_call_leaves(graph)
    }

    fn owned_vec_has_free(graph: &FunctionGraph) -> bool {
        owned_vec_leaves(graph)
            .iter()
            .any(|leaf| leaf.starts_with("ll_vec_free"))
    }

    fn owned_vec_has_alloc(graph: &FunctionGraph) -> bool {
        owned_vec_leaves(graph)
            .iter()
            .any(|leaf| leaf.starts_with("ll_vec_newemptylist"))
    }

    fn drop_term_is_goto(
        body: &majit_charon_reader::ullbc::Unstructured,
        llbc: &Llbc,
        bb: usize,
    ) -> bool {
        matches!(
            body.body[bb].term(llbc),
            Ok(majit_charon_reader::ullbc::TermKind::Goto { .. })
        )
    }

    fn drop_term_is_drop(
        body: &majit_charon_reader::ullbc::Unstructured,
        llbc: &Llbc,
        bb: usize,
    ) -> bool {
        matches!(
            body.body[bb].term(llbc),
            Ok(majit_charon_reader::ullbc::TermKind::Drop { .. })
        )
    }

    /// A definitely-initialised `Vec` Drop stays a Drop and lowers to
    /// `ll_vec_free_*` at that terminator, the `rewrite_op_free` site.
    #[test]
    fn rust_vec_drop_of_definitely_init_vec_frees_at_the_drop() {
        let vec_ty = owned_vec_ty();
        let unit = owned_vec_unit_ty();
        let name = "drop_init_vec";
        let llbc = owned_vec_drop_llbc(
            name,
            0,
            vec![owned_vec_local(0, &unit), owned_vec_local(1, &vec_ty)],
            vec![
                owned_vec_block(vec![], owned_vec_new_call(1, &vec_ty, 1, 3)),
                owned_vec_block(vec![], owned_vec_drop(1, &vec_ty, 2, 3)),
                owned_vec_return_unit(&unit),
                owned_vec_block(vec![], serde_json::json!("UnwindResume")),
            ],
            vec![],
            vec![],
        );
        let mut body = llbc.local_fn(name).unwrap().unstructured().unwrap();
        super::elaborate_vec_drops(&llbc, &mut body);
        assert!(
            drop_term_is_drop(&body, &llbc, 1),
            "definitely-init Drop stays a Drop"
        );
        assert_eq!(
            super::vec_init_at_drop(&body, &llbc, 1, 1),
            super::VecInit::Init
        );
        let graph = super::lower_function(&llbc, name).expect("lower drop_init_vec");
        let leaves = owned_vec_leaves(&graph);
        assert!(owned_vec_has_alloc(&graph), "must allocate: {leaves:?}");
        assert!(
            owned_vec_has_free(&graph),
            "definitely-init Drop must free at the Drop: {leaves:?}"
        );
    }

    /// A `Vec` moved into a call is uninitialised at the trailing Drop;
    /// elaboration turns that Drop into a Goto, so this graph does not free.
    #[test]
    fn rust_vec_drop_after_move_into_call_does_not_free() {
        let vec_ty = owned_vec_ty();
        let unit = owned_vec_unit_ty();
        let name = "drop_moved_into_call_vec";
        let sink = serde_json::json!({"Call": {
            "call": {
                "func": {"Regular": {
                    "kind": {"Fun": 2},
                    "generics": {
                        "regions": [],
                        "types": [],
                        "const_generics": [],
                        "trait_refs": []
                    }
                }},
                "args": [{"Move": owned_vec_place(1, &vec_ty)}],
                "dest": owned_vec_place(2, &unit)
            },
            "target": 2,
            "on_unwind": 4
        }});
        let llbc = owned_vec_drop_llbc(
            name,
            0,
            vec![
                owned_vec_local(0, &unit),
                owned_vec_local(1, &vec_ty),
                owned_vec_local(2, &unit),
            ],
            vec![
                owned_vec_block(vec![], owned_vec_new_call(1, &vec_ty, 1, 4)),
                owned_vec_block(vec![], sink),
                owned_vec_block(vec![], owned_vec_drop(1, &vec_ty, 3, 4)),
                owned_vec_return_unit(&unit),
                owned_vec_block(vec![], serde_json::json!("UnwindResume")),
            ],
            vec![],
            vec![],
        );
        let mut body = llbc.local_fn(name).unwrap().unstructured().unwrap();
        super::elaborate_vec_drops(&llbc, &mut body);
        assert!(
            drop_term_is_goto(&body, &llbc, 2),
            "moved-out Drop becomes Goto"
        );
        let graph = super::lower_function(&llbc, name).expect("lower drop_moved_into_call_vec");
        let leaves = owned_vec_leaves(&graph);
        assert!(owned_vec_has_alloc(&graph), "must allocate: {leaves:?}");
        assert!(
            !owned_vec_has_free(&graph),
            "moved-into-call must not free: {leaves:?}"
        );
    }

    /// A `Vec` stored into a struct field is uninitialised at the trailing
