    fn deref_impl(
        trait_id: u64,
        self_ty: serde_json::Value,
        targets: Vec<serde_json::Value>,
        witnesses: Vec<serde_json::Value>,
    ) -> serde_json::Value {
        let types = targets
            .into_iter()
            .enumerate()
            .map(|(index, target)| {
                serde_json::json!({
                    "kind": {"TraitType": [trait_id, index]},
                    "skip_binder": {"value": target}
                })
            })
            .collect::<Vec<_>>();
        serde_json::json!({
            "impl_trait": {
                "id": trait_id,
                "generics": {
                    "regions": [],
                    "types": [self_ty],
                    "const_generics": [],
                    "trait_refs": []
                }
            },
            "types": types,
            "witnesses": witnesses
        })
    }

