    /// A transparent GC-ref wrapper keeps its own class. The handle intern's
    /// as a subclass of `Deref::Target`; the payload row stays a pointer to
    /// that target.
    #[test]
    fn transparent_gc_handle_keeps_the_wrapper_class() {
        let decls = pointer_handle_decls();
        let blanket = serde_json::json!({
            "impl_trait": {
                "id": 1,
                "generics": {"types": [{"TypeVar": {"Bound": [0, 0]}}]}
            },
            "types": [{
                "kind": {"TraitType": [1, 0]},
                "skip_binder": {"value": adt_body(4)}
            }]
        });
        let (llbc, ty) = load_handle(
            decls.clone(),
            serde_json::json!([null, blanket, pyerror_deref_impl(23, 2)]),
            3,
        );
        let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        assert_eq!(
            super::tyref_to_value_type(&ty, &llbc),
            ValueType::Ref(Some("PyError".into()))
        );
        assert_handle_class(&llbc, &ty, Some("PyError"));
        // The payload row is one pointer to the Deref target. A bare
        // `PyErrorObject` would be laid out as the whole object.
        assert_eq!(
            super::tyref_to_field_layout_string(&ty, &llbc, &gc_struct_ids),
            "*mut PyErrorObject"
        );
        // A captured `&PyError` keeps the handle class, not the payload
        // pointer `transparent_handle_field_spelling` would paint after
        // peeling `&`.
        let shared = serde_json::from_value::<TyRef>(serde_json::json!({
            "Value": [9104, {"Ref": ["Erased", adt_body(3), "Shared"]}]
        }))
        .expect("shared-borrow TyRef parses");
        assert_eq!(
            super::tyref_to_field_layout_string(&shared, &llbc, &gc_struct_ids),
            "&PyError"
        );
        let ptr = serde_json::from_value::<TyRef>(serde_json::json!({
            "Value": [9103, {"RawPtr": [adt_body(3), "Mut"]}]
        }))
        .expect("pointer TyRef parses");
        assert_eq!(
            super::enum_payload_instance_class_root(&ptr, &llbc, no_tombstoned_leaves()).as_deref(),
            Some("PyError")
        );
        assert_eq!(
            super::tyref_to_field_layout_string(&ptr, &llbc, &gc_struct_ids),
            "*mut PyErrorObject"
        );

        let same_class = paint_handle(
            decls.clone(),
            serde_json::json!([pyerror_deref_impl(23, 2), pyerror_deref_impl(25, 2)]),
            3,
        );
        assert_eq!(same_class, ValueType::Ref(Some("PyError".into())));

        let (llbc, ty) = load_handle(decls.clone(), serde_json::json!([null]), 3);
        let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        assert_eq!(super::tyref_to_value_type(&ty, &llbc), ValueType::Ref(None));
        assert_handle_class(&llbc, &ty, Some("PyError"));
        assert_eq!(
            super::tyref_to_field_layout_string(&ty, &llbc, &gc_struct_ids),
            "PyError"
        );

        let mut scalar_decls = decls.clone();
        scalar_decls[2] = (
            3,
            struct_decl(3, ident_path(&["fixture", "Word"]), i64_field(), true),
        );
        let (llbc, ty) = load_handle(
            scalar_decls,
            serde_json::json!([pyerror_deref_impl(23, 2)]),
            3,
        );
        let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        assert_eq!(super::tyref_to_value_type(&ty, &llbc), ValueType::Int);
        assert_handle_class(&llbc, &ty, Some("Word"));
        assert_eq!(
            super::tyref_to_field_layout_string(&ty, &llbc, &gc_struct_ids),
            "i64"
        );

        let split = paint_handle(
            decls.clone(),
            serde_json::json!([pyerror_deref_impl(23, 2), pyerror_deref_impl(24, 4)]),
            3,
        );
        assert_eq!(split, ValueType::Ref(None));

        let ambiguous = deref_impl(
            1,
            serde_json::json!({"Deduplicated": 22}),
            vec![
                serde_json::json!({"Deduplicated": 23}),
                serde_json::json!({"Deduplicated": 24}),
            ],
            vec![
                serde_json::json!({"Value": [22, adt_body(3)]}),
                serde_json::json!({"Value": [23, adt_body(2)]}),
                serde_json::json!({"Value": [24, adt_body(4)]}),
            ],
        );
        assert_eq!(
            paint_handle(decls.clone(), serde_json::json!([ambiguous]), 3),
            ValueType::Ref(None)
        );

        let vec_target = serde_json::json!({
            "Adt": {
                "id": 5,
                "generics": {"types": [{"Scalar": {"Integer": {"Signed": "I64"}}}]}
            }
        });
        let no_class = deref_impl(
            1,
            serde_json::json!({"Deduplicated": 22}),
            vec![serde_json::json!({"Deduplicated": 26})],
            vec![
                serde_json::json!({"Value": [22, adt_body(3)]}),
                serde_json::json!({"Value": [26, vec_target]}),
            ],
        );
        assert_eq!(
            paint_handle(decls, serde_json::json!([no_class]), 3),
            ValueType::Ref(None)
        );

        let mut copy_name = ident_path(&["fixture", "Handle"]);
        copy_name
            .as_array_mut()
            .expect("path")
            .push(serde_json::json!({
                "Instantiated": {"skip_binder": {"types": [{"Scalar": "Bool"}]}}
            }));
        let mut other_copy = ident_path(&["fixture", "Handle"]);
        other_copy
            .as_array_mut()
            .expect("path")
            .push(serde_json::json!({
                "Instantiated": {"skip_binder": {"types": [
                    {"Scalar": {"Integer": {"Signed": "I64"}}}
                ]}}
            }));
        let copies = vec![
            (
                1,
                struct_decl(
                    1,
                    ident_path(&["fixture", "PyObject"]),
                    empty_fields(),
                    false,
                ),
            ),
            (
                2,
                struct_decl(
                    2,
                    ident_path(&["fixture", "PyErrorObject"]),
                    empty_fields(),
                    false,
                ),
            ),
            (6, struct_decl(6, copy_name, raw_ptr_field(1), true)),
            (7, struct_decl(7, other_copy, raw_ptr_field(1), true)),
        ];
        let copy_impl = deref_impl(
            1,
            serde_json::json!({"Deduplicated": 22}),
            vec![serde_json::json!({"Deduplicated": 23})],
            vec![
                serde_json::json!({"Value": [22, adt_body(6)]}),
                serde_json::json!({"Value": [23, adt_body(2)]}),
            ],
        );
        let (llbc, ty) = load_handle(copies, serde_json::json!([copy_impl]), 7);
        assert_eq!(
            super::tyref_to_value_type(&ty, &llbc),
            ValueType::Ref(Some("Handle".into()))
        );
        assert_handle_class(&llbc, &ty, Some("Handle"));
    }

    fn opaque_handle_decl(def_id: u64, name: serde_json::Value, size: u64) -> serde_json::Value {
        let mut decl = serde_json::json!({
            "def_id": def_id,
            "item_meta": fixture_item_meta(name),
            "kind": "Opaque"
        });
        let mut layout = transparent_layout();
        layout[0]["value"]["size"] = serde_json::json!(size);
        layout[0]["value"]["align"] = serde_json::json!(size);
        decl["layout"] = layout;
        decl
    }

    fn load_handle_with_width(
        type_decls: Vec<(u64, serde_json::Value)>,
        trait_impls: serde_json::Value,
        query: u64,
        pointer_size: Option<u8>,
    ) -> (Llbc, TyRef) {
        let trait_impls = with_fixture_gctype_impls(&type_decls, trait_impls);
        let mut translated = serde_json::json!({
            "crate_name": "fixture",
            "type_decls": indexed_rows(type_decls),
            "fun_decls": [],
            "global_decls": [],
            "trait_decls": handle_trait_decls(),
            "trait_impls": trait_impls
        });
        if let Some(width) = pointer_size {
            translated["target_information"] = serde_json::json!([{
                "key": "fixture-target",
                "value": {
                    "target_pointer_size": width,
                    "is_little_endian": true
                }
            }]);
        }
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": translated
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
        let ty = serde_json::from_value::<TyRef>(serde_json::json!({
            "Value": [9000 + query, adt_body(query)]
        }))
        .expect("query TyRef parses");
        (llbc, ty)
    }

    /// An external `repr(transparent)` handle is `Opaque`. The wrapper
    /// keeps its own class; the payload row is a pointer to `Deref::Target`.
    #[test]
    fn opaque_transparent_gc_handle_keeps_the_wrapper_class() {
        let mut decls = pointer_handle_decls();
        decls[2] = (
            3,
            opaque_handle_decl(3, ident_path(&["fixture", "PyError"]), 8),
        );
        let (llbc, ty) = load_handle_with_width(
            decls.clone(),
            serde_json::json!([pyerror_deref_impl(23, 2)]),
            3,
            Some(8),
        );
        let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        assert_eq!(
            super::tyref_to_value_type(&ty, &llbc),
            ValueType::Ref(Some("PyError".into()))
        );
        assert_handle_class(&llbc, &ty, Some("PyError"));
        assert_eq!(
            super::tyref_to_field_layout_string(&ty, &llbc, &gc_struct_ids),
            "*mut PyErrorObject"
        );

        // The target struct is `Opaque` in a crate that never reads its
        // fields. The class is still the nominal leaf.
        let mut opaque_target = decls.clone();
        opaque_target[1] = (
            2,
            serde_json::json!({
                "def_id": 2,
                "item_meta": fixture_item_meta(ident_path(&["fixture", "PyErrorObject"])),
                "kind": "Opaque"
            }),
        );
        let (llbc, ty) = load_handle_with_width(
            opaque_target,
            serde_json::json!([pyerror_deref_impl(23, 2)]),
            3,
            Some(8),
        );
        assert_eq!(
            super::tyref_to_value_type(&ty, &llbc),
            ValueType::Ref(Some("PyError".into()))
        );
        assert_handle_class(&llbc, &ty, Some("PyError"));

        // No extraction target: the width is unknown, so the opaque
        // view does not guess a class.
        let (llbc, ty) = load_handle_with_width(
            decls.clone(),
            serde_json::json!([pyerror_deref_impl(23, 2)]),
            3,
            None,
        );
        assert_eq!(super::tyref_to_value_type(&ty, &llbc), ValueType::Ref(None));
        assert_handle_class(&llbc, &ty, Some("PyError"));

        // A narrower transparent word is not this handle.
        decls[2] = (
            3,
            opaque_handle_decl(3, ident_path(&["fixture", "Narrow"]), 4),
        );
        let (llbc, ty) = load_handle_with_width(
            decls.clone(),
            serde_json::json!([pyerror_deref_impl(23, 2)]),
            3,
            Some(8),
        );
        assert_eq!(super::tyref_to_value_type(&ty, &llbc), ValueType::Ref(None));
        assert_handle_class(&llbc, &ty, Some("Narrow"));

        // A linked scalar keeps its bank even when a `Deref` impl is
        // present. The class rule runs before the scalar peel.
        decls[2] = (
            3,
            opaque_handle_decl(3, ident_path(&["fixture", "Word"]), 8),
        );
        let (llbc, ty) = load_handle_with_width(
            decls,
            serde_json::json!([pyerror_deref_impl(23, 2)]),
            3,
            Some(8),
        );
        llbc.register_transparent_scalar_kinds([(
            "fixture::Word".to_string(),
            majit_charon_reader::TransparentScalarKind::Signed,
        )]);
        assert_eq!(super::tyref_to_value_type(&ty, &llbc), ValueType::Int);
        assert_handle_class(&llbc, &ty, Some("Word"));
    }

    /// `celldict.py` `erase({})`: a by-value transparent newtype intern's
    /// as the inner struct, so unique-graph `mergeinputargs` unifies the
    /// wrapper with that operand (`rordereddict.rtype_len`).
    #[test]
    fn by_value_transparent_newtype_interns_as_inner_struct() {
        let inner = {
            let mut decl = struct_decl(1, ident_path(&["fixture", "RDict"]), i64_field(), false);
            decl["layout"] = serde_json::json!([{
                "key": "fixture-target",
                "value": {
                    "size": 8,
                    "align": 8,
                    "variant_layouts": [{"field_offsets": [0]}],
                    "repr": {"repr_algo": "Rust", "transparent": false}
                }
            }]);
            decl
        };
        let wrapper_field = serde_json::json!([{
            "name": null,
            "ty": {"Adt": {"id": 1, "generics": {"types": []}}},
            "attr_info": null
        }]);
        let wrapper = struct_decl(
            2,
            ident_path(&["fixture", "ModuleDictStorage"]),
            wrapper_field,
            true,
        );
        let alias = serde_json::json!({
            "def_id": 3,
            "item_meta": fixture_item_meta(ident_path(&["fixture", "ModuleDictEntries"])),
            "kind": {"Alias": {
                "aliased_ty": {"Adt": {"id": 1, "generics": {"types": []}}}
            }}
        });
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": indexed_rows(vec![(1, inner), (2, wrapper), (3, alias)]),
                "fun_decls": [],
                "global_decls": [],
                "trait_decls": [],
                "trait_impls": []
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
        let tomb = no_tombstoned_leaves();
        let storage = serde_json::from_value::<TyRef>(serde_json::json!({
            "Value": [2, {"Adt": {"id": 2, "generics": {"types": []}}}]
        }))
        .expect("storage TyRef parses");
        let entries = serde_json::from_value::<TyRef>(serde_json::json!({
            "Value": [3, {"Adt": {"id": 3, "generics": {"types": []}}}]
        }))
        .expect("entries TyRef parses");
        let dict = serde_json::from_value::<TyRef>(serde_json::json!({
            "Value": [1, {"Adt": {"id": 1, "generics": {"types": []}}}]
        }))
        .expect("dict TyRef parses");
        assert_eq!(
            super::tyref_class_root_with(&storage, &llbc, tomb).as_deref(),
            Some("RDict")
        );
        assert_eq!(
            super::tyref_class_root_with(&entries, &llbc, tomb).as_deref(),
            Some("RDict")
        );
        assert_eq!(
            super::tyref_class_root_with(&dict, &llbc, tomb).as_deref(),
            Some("RDict")
        );
    }

    /// A transparent wrapper of `*mut PyObject` stays the wrapper.
    /// `StrKey`'s `*mut Utf8Str` and a scalar newtype still erase to the word.
    #[test]
    fn borrowed_one_scalar_struct_uses_the_field_bank() {
        let type_decl = serde_json::json!({
            "def_id": 1,
            "item_meta": {
                "name": [{"Ident": ["fixture", 0]}, {"Ident": ["DepthWord", 0]}],
                "span": {"data": {
                    "file_id": 0,
                    "beg": {"line": 1, "col": 0},
                    "end": {"line": 4, "col": 1}
                }},
                "source_text": "struct Anchor { depth: usize, _not_send: () }",
                "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                "is_local": true
            },
            "kind": {"Struct": [
                {
                    "name": "depth",
                    "ty": {"Value": [7, {"Scalar": {"Integer": {"Unsigned": "Usize"}}}]},
                    "attr_info": null
                },
                {
                    "name": "_not_send",
                    "ty": {"Value": [9, {"Adt": {"id": 0, "builtin": "Tuple", "generics": {"types": []}}}]},
                    "attr_info": null
                }
            ]},
            "layout": [{
                "key": "aarch64-apple-darwin",
                "value": {
                    "size": 8,
                    "align": 8,
                    "variant_layouts": [{"field_offsets": [0, 8]}],
                    "repr": {"repr_algo": "Rust", "transparent": true}
                }
            }]
        });
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [null, type_decl],
                "fun_decls": [],
                "global_decls": [],
                "trait_decls": [],
                "trait_impls": []
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
        let borrowed = serde_json::from_value::<super::TyRef>(serde_json::json!({
            "Value": [8, {
                "Ref": ["r", {
                    "Adt": {"id": 1, "generics": {"types": []}}
                }, "Shared"]
            }]
        }))
        .expect("borrowed TyRef parses");
        assert_eq!(
            super::tyref_to_value_type(&borrowed, &llbc),
            crate::model::ValueType::Unsigned
        );
    }

    /// `fn f<T>(x: &T)` stays generic on the declaration. The call
    /// instantiates `T` with a `repr(transparent)` scalar wrapper, so the
    /// residual must be refused; the same callee with a non-transparent
    /// `T` still lowers.
    #[test]
    fn generic_residual_borrow_of_transparent_scalar_is_refused() {
        let span = || {
            serde_json::json!({"data": {
                "file_id": 0,
                "beg": {"line": 1, "col": 0},
                "end": {"line": 1, "col": 1}
            }})
        };
        let item_meta = |path: &[&str], is_local: bool| {
            serde_json::json!({
                "name": path
                    .iter()
                    .map(|segment| serde_json::json!({"Ident": [segment, 0]}))
                    .collect::<Vec<_>>(),
                "span": span(),
                "source_text": null,
                "attr_info": {
                    "attributes": [],
                    "inline": null,
                    "rename": null,
                    "public": true
                },
                "is_local": is_local
            })
        };
        let struct_decl = |def_id: u64, leaf: &str, transparent: bool| {
            serde_json::json!({
                "def_id": def_id,
                "item_meta": item_meta(&["fixture", leaf], true),
                "kind": {"Struct": [{
                    "name": null,
                    "ty": {"Scalar": {"Integer": {"Signed": "I64"}}},
                    "attr_info": null
                }]},
                "layout": [{
                    "key": "fixture-target",
                    "value": {
                        "size": 8,
                        "align": 8,
                        "variant_layouts": [{"field_offsets": [0]}],
                        "repr": {"repr_algo": "Rust", "transparent": transparent}
                    }
                }]
            })
        };
        let adt = |def_id: u64| {
            serde_json::json!({
                "Adt": {"id": def_id, "generics": {"types": []}}
            })
        };
        let borrowed =
            |inner: serde_json::Value| serde_json::json!({"Ref": ["_", inner, "Shared"]});
        let type_var = serde_json::json!({"TypeVar": {"Bound": [0, 0]}});
        let unit = serde_json::json!({"Tuple": []});
        let caller = |def_id: u64, name: &str, type_arg: serde_json::Value| {
            let arg_ty = borrowed(type_arg.clone());
            serde_json::json!({
                "def_id": def_id,
                "item_meta": item_meta(&["fixture", name], true),
                "signature": {
                    "is_unsafe": false,
                    "inputs": [arg_ty.clone()],
                    "output": unit.clone()
                },
                "body": {
                    "Unstructured": {
                        "span": span(),
                        "locals": {
                            "arg_count": 1,
                            "locals": [
                                {"index": 0, "name": null, "span": span(), "ty": unit.clone()},
                                {"index": 1, "name": "value", "span": span(), "ty": arg_ty.clone()}
                            ]
                        },
                        "body": [
                            {
                                "statements": [],
                                "terminator": {
                                    "span": span(),
                                    "kind": {
                                        "Call": {
                                            "call": {
                                                "func": {
                                                    "Regular": {
                                                        "kind": {"Fun": 2},
                                                        "generics": {
                                                            "regions": [],
                                                            "types": [type_arg],
                                                            "const_generics": [],
                                                            "trait_refs": []
                                                        }
                                                    }
                                                },
                                                "args": [{
                                                    "Copy": {
                                                        "kind": {"Local": 1},
                                                        "ty": arg_ty.clone()
                                                    }
                                                }],
                                                "dest": {"kind": {"Local": 0}, "ty": unit.clone()}
                                            },
                                            "target": 2,
                                            "on_unwind": 1
                                        }
                                    }
                                }
                            },
                            {
                                "statements": [],
                                "terminator": {"span": span(), "kind": "UnwindResume"}
                            },
                            {
                                "statements": [],
                                "terminator": {"span": span(), "kind": "Return"}
                            }
                        ]
                    }
                }
            })
        };
        let callee = serde_json::json!({
            "def_id": 2,
            "item_meta": item_meta(&["fixture", "f"], false),
            "signature": {
                "is_unsafe": false,
                "inputs": [borrowed(type_var)],
                "output": unit
            },
            "body": "Opaque"
        });
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [
                    struct_decl(0, "Word", true),
                    struct_decl(1, "Plain", false)
                ],
                "fun_decls": [
                    caller(0, "pass_word", adt(0)),
                    caller(1, "pass_plain", adt(1)),
                    callee
                ],
                "global_decls": [],
                "trait_decls": [],
                "trait_impls": []
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");

        let refused = super::lower_function(&llbc, "pass_word")
            .expect_err("borrow of a transparent scalar wrapper must be refused");
        let refused = refused.to_string();
        assert!(
            refused.contains("repr(transparent) scalar"),
            "refusal must name the scalar borrow, got {refused}"
        );

        let graph = super::lower_function(&llbc, "pass_plain")
            .expect("a non-transparent T must still lower");
        let ops = graph_ops(&graph);
        assert!(
            call_leafs(&ops).iter().any(|leaf| leaf == "f"),
            "non-transparent instantiation must stay a residual call; ops={ops:?}"
        );
    }

    #[test]
    fn atomic_field_layout_string_is_the_inner_scalar() {
        let atomic_decl = |def_id: u64, size: u64| {
            serde_json::json!({
                "def_id": def_id,
                "item_meta": {
                    "name": [
                        {"Ident": ["core", 0]},
                        {"Ident": ["sync", 0]},
                        {"Ident": ["atomic", 0]},
                        {"Ident": ["Atomic", 0]}
                    ],
                    "span": {"data": {
                        "file_id": 0,
                        "beg": {"line": 1, "col": 0},
                        "end": {"line": 1, "col": 8}
                    }},
                    "source_text": "pub struct Atomic;",
                    "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                    "is_local": false
                },
                // Opaque: the scalar spelling comes from the `Atomic<T>`
                // type argument, not from reading its storage payload,
                // which a dependency artefact does not carry.
                "kind": "Opaque",
                "layout": [{
                    "key": "x86_64-unknown-linux-gnu",
                    "value": {
                        "size": size,
                        "align": size,
                        "variant_layouts": [{"field_offsets": [0]}],
                        "repr": {"repr_algo": "Rust", "transparent": false}
                    }
                }]
            })
        };
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [
                    null,
                    atomic_decl(1, 8)
                ],
                "fun_decls": [],
                "global_decls": [],
                "trait_decls": [],
                "trait_impls": []
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
        let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        let adt_ty = |def_id: u64, args: serde_json::Value| {
            serde_json::from_value::<super::TyRef>(serde_json::json!({
                "Value": [8, {
                    "Adt": {"id": def_id, "generics": {"types": args}}
                }]
            }))
            .expect("fixture TyRef parses")
        };

        // An integer atomic spells as the scalar it is layout-transparent
        // over, so the string-keyed field tables land on the same `Int` the
        // runtime publishes rather than their unknown-name `Ref` wildcard.
        // `AtomicUsize` is the alias `Atomic<usize>`.
        let usize_ty = adt_ty(
            1,
            serde_json::json!([{"Scalar": {"Integer": {"Unsigned": "Usize"}}}]),
        );
        assert_eq!(
            super::tyref_to_field_layout_string(&usize_ty, &llbc, &gc_struct_ids),
            "usize"
        );
        assert_eq!(
            crate::codewriter::call::get_type_flag("usize").1,
            majit_ir::value::Type::Int
        );

        // `AtomicPtr<T>` (`Atomic<*mut T>`) is a pointer word. Spell it as
        // the actual `*mut T` so fielddescrof does not treat the wrapper as
        // a nested struct, and so a non-GC pointee is not erased to
        // `PyObject`.
        let ptr_ty = adt_ty(
            1,
            serde_json::json!([{"RawPtr": [{"Scalar": {"Integer": {"Unsigned": "U8"}}}, "Mut"]}]),
        );
        let ptr_str = super::tyref_to_field_layout_string(&ptr_ty, &llbc, &gc_struct_ids);
        assert_eq!(ptr_str, "*mut u8");
        assert_eq!(
            crate::codewriter::call::get_type_flag(&ptr_str).1,
            majit_ir::value::Type::Ref
        );
    }

    #[test]
    fn fieldless_enum_field_layout_is_its_discriminant_scalar() {
        let type_decl = serde_json::json!({
            "def_id": 1,
            "item_meta": {
                "name": [{"Ident": ["fixture", 0]}, {"Ident": ["AccessMode", 0]}],
                "span": {"data": {
                    "file_id": 0,
                    "beg": {"line": 1, "col": 0},
                    "end": {"line": 1, "col": 32}
                }},
                "source_text": "enum AccessMode { ReadWrite, ReadOnly }",
                "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                "is_local": true
            },
            "kind": {"Enum": [
                {"name": "ReadWrite", "fields": [], "discriminant": 0, "attr_info": null},
                {"name": "ReadOnly", "fields": [], "discriminant": 1, "attr_info": null}
            ]},
            "layout": [{
                "key": "x86_64-unknown-linux-gnu",
                "value": {
                    "size": 1,
                    "align": 1,
                    "discriminator": {"Branch": {
                        "offset": 0,
                        "int_ty": {"Unsigned": "U8"}
                    }},
                    "variant_layouts": [
                        {"field_offsets": []},
                        {"field_offsets": []}
                    ],
                    "repr": {"repr_algo": "Rust", "transparent": false}
                }
            }]
        });
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [null, type_decl],
                "fun_decls": [],
                "global_decls": [],
                "trait_decls": [],
                "trait_impls": []
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
        let enum_ty = serde_json::from_value::<super::TyRef>(serde_json::json!({
            "Value": [8, {
                "Adt": {"id": 1, "generics": {"types": []}}
            }]
        }))
        .expect("fixture TyRef parses");
        let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();

        assert_eq!(
            super::tyref_to_field_layout_string(&enum_ty, &llbc, &gc_struct_ids),
            "u8"
        );
        assert_eq!(
            crate::codewriter::call::get_type_flag("u8"),
            (
                majit_ir::descr::ArrayFlag::Unsigned,
                majit_ir::value::Type::Int,
                1,
            )
        );
    }

    /// A closure env whose capture is a fieldless enum (by shared
    /// borrow, the rustc capture of a `Copy` tag) keeps that word as
    /// the discriminant integer. `typed_ref_field_narrow_root` must
    /// not emit `__cast_instance_intrinsic` against the enum class
    /// (`rclass.py` `pairtype(InstanceRepr, InstanceRepr).convert_from_to`
    /// has no integer operand), and the lowered graph must annotate.
    #[test]
    fn closure_capturing_fieldless_enum_annotates() {
        use crate::annotator::annrpython::RPythonAnnotator;
        use crate::annotator::model::{SomeInteger, SomeValue};
        use crate::translator::rtyper::call_registry::CallRegistry;
        use crate::translator::rtyper::flowspace_adapter::function_graph_to_flowspace;
        use std::rc::Rc;

        let span = serde_json::json!({"data": {
            "file_id": 0,
            "beg": {"line": 1, "col": 0},
            "end": {"line": 1, "col": 32}
        }});
        let generics = serde_json::json!({
            "regions": [], "types": [], "const_generics": [], "trait_refs": []
        });
        let enum_adt = serde_json::json!({"Adt": {"id": 1, "generics": generics}});
        let borrowed_enum = serde_json::json!({"Ref": ["_", enum_adt.clone(), "Shared"]});
        let closure_adt = serde_json::json!({"Adt": {"id": 2, "generics": generics}});
        let u8_ty = serde_json::json!({"Scalar": {"Integer": {"Unsigned": "U8"}}});
        let place =
            |id: u64, ty: &serde_json::Value| serde_json::json!({"kind": {"Local": id}, "ty": ty});
        // rustc `call_once` of a capturing closure reads the tag as
        // `Discriminant(*&E)`. The place type after Deref is the enum;
        // the inner is the captured borrow.
        let deref_enum = serde_json::json!({
            "kind": {"Projection": [place(1, &borrowed_enum), "Deref"]},
            "ty": enum_adt
        });
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [
                    null,
                    {
                        "def_id": 1,
                        "item_meta": {
                            "name": [{"Ident": ["fixture", 0]}, {"Ident": ["AccessMode", 0]}],
                            "span": span, "source_text": "enum AccessMode { ReadWrite, ReadOnly }",
                            "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                            "is_local": true
                        },
                        "kind": {"Enum": [
                            {"name": "ReadWrite", "fields": [], "discriminant": 0, "attr_info": null},
                            {"name": "ReadOnly", "fields": [], "discriminant": 1, "attr_info": null}
                        ]},
                        "layout": [{
                            "key": "x86_64-unknown-linux-gnu",
                            "value": {
                                "size": 1, "align": 1,
                                "discriminator": {"Branch": {
                                    "offset": 0,
                                    "int_ty": {"Unsigned": "U8"}
                                }},
                                "variant_layouts": [
                                    {"field_offsets": []},
                                    {"field_offsets": []}
                                ],
                                "repr": {"repr_algo": "Rust", "transparent": false}
                            }
                        }]
                    },
                    {
                        "def_id": 2,
                        "item_meta": {
                            "name": [
                                {"Ident": ["fixture", 0]},
                                {"Ident": ["capture", 0]},
                                {"Ident": ["closure", 0]}
                            ],
                            "span": span, "source_text": null,
                            "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                            "is_local": true
                        },
                        "kind": {"Struct": [{
                            "name": null,
                            "ty": borrowed_enum.clone(),
                            "attr_info": {"attributes": [], "inline": null, "rename": null, "public": false}
                        }]},
                        "layout": [{
                            "key": "x86_64-unknown-linux-gnu",
                            "value": {
                                "size": 1, "align": 1,
                                "variant_layouts": [{"field_offsets": [0]}],
                                "repr": {"repr_algo": "Rust", "transparent": false}
                            }
                        }],
                        "src": {"Closure": {"info": {"kind": "FnOnce"}}}
                    }
                ],
                "fun_decls": [{
                    "def_id": 0,
                    "item_meta": {
                        "name": [{"Ident": ["fixture", 0]}, {"Ident": ["capture", 0]}],
                        "span": span, "source_text": null,
                        "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                        "is_local": true
                    },
                    "signature": {
                        "is_unsafe": false,
                        "inputs": [borrowed_enum.clone()],
                        "output": closure_adt.clone()
                    },
                    "body": {"Unstructured": {
                        "span": span,
                        "locals": {"arg_count": 1, "locals": [
                            {"index": 0, "name": null, "span": span, "ty": closure_adt.clone()},
                            {"index": 1, "name": "op", "span": span, "ty": borrowed_enum.clone()}
                        ]},
                        "body": [
                            {"statements": [{
                                "span": span,
                                "kind": {"Assign": [
                                    place(0, &closure_adt),
                                    {"Aggregate": [
                                        {"Adt": [2, null, null, generics.clone()]},
                                        [{"Copy": place(1, &borrowed_enum)}]
                                    ]}
                                ]}
                            }],
                            "terminator": {"span": span, "kind": "Return"}},
                            {"statements": [],
                             "terminator": {"span": span, "kind": "UnwindResume"}}
                        ]
                    }}
                }, {
                    "def_id": 1,
                    "item_meta": {
                        "name": [{"Ident": ["fixture", 0]}, {"Ident": ["tag", 0]}],
                        "span": span, "source_text": null,
                        "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                        "is_local": true
                    },
                    "signature": {
                        "is_unsafe": false,
                        "inputs": [borrowed_enum.clone()],
                        "output": u8_ty.clone()
                    },
                    "body": {"Unstructured": {
                        "span": span,
                        "locals": {"arg_count": 1, "locals": [
                            {"index": 0, "name": null, "span": span, "ty": u8_ty.clone()},
                            {"index": 1, "name": "op", "span": span, "ty": borrowed_enum.clone()}
                        ]},
                        "body": [
                            {"statements": [{
                                "span": span,
                                "kind": {"Assign": [
                                    place(0, &u8_ty),
                                    {"Discriminant": deref_enum}
                                ]}
                            }],
                            "terminator": {"span": span, "kind": "Return"}},
                            {"statements": [],
                             "terminator": {"span": span, "kind": "UnwindResume"}}
                        ]
                    }}
                }],
                "global_decls": [], "trait_decls": [], "trait_impls": []
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
        let borrowed_ty = serde_json::from_value::<super::TyRef>(borrowed_enum.clone())
            .expect("borrowed fieldless TyRef parses");
        let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        let env = llbc.type_by_id(2).expect("closure env");

        assert!(
            !super::ty_is_raw_address(&borrowed_ty, &llbc, &gc_struct_ids),
            "a borrow of a fieldless enum is the tag integer, not a raw address"
        );
        assert_eq!(
            super::tyref_to_field_layout_string(&borrowed_ty, &llbc, &gc_struct_ids),
            "u8",
            "a borrow of a fieldless enum is the discriminant scalar"
        );
        assert_eq!(
            tyref_to_attr_value_type(&borrowed_ty, &llbc),
            ValueType::Int,
            "FORCE must seed Integer for a captured &E tag"
        );
        assert_eq!(
            tyref_to_attr_value_type_for_struct_field(&borrowed_ty, env, &llbc, &gc_struct_ids),
            ValueType::Int,
            "closure-env FORCE rows match the Int-banked capture"
        );

        let graph = super::lower_function(&llbc, "capture").expect("lower capture");
        let cast_roots: Vec<&str> = graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .filter_map(|op| crate::model::cast_instance_root(&op.kind))
            .collect();
        assert!(
            cast_roots.is_empty(),
            "fieldless-enum capture must not emit __cast_instance_intrinsic; roots={cast_roots:?}"
        );

        let tag_graph = super::lower_function(&llbc, "tag").expect("lower tag");
        let tag_ops: Vec<&crate::model::OpKind> = tag_graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .map(|op| &op.kind)
            .collect();
        assert!(
            tag_ops
                .iter()
                .all(|kind| !matches!(kind, crate::model::OpKind::RawLoad { .. })),
            "Discriminant(*&E) of a fieldless enum is the tag, not a raw_load; ops={tag_ops:?}"
        );
        assert!(
            tag_ops.iter().all(|kind| {
                !matches!(
                    kind,
                    crate::model::OpKind::BinOp { op, .. } if op == "and_" || op == "&" || op == "and"
                )
            }),
            "fieldless Discriminant must not mask a loaded tag; ops={tag_ops:?}"
        );
        let tag_cast_roots: Vec<&str> = tag_ops
            .iter()
            .filter_map(|kind| crate::model::cast_instance_root(kind))
            .collect();
        assert!(
            tag_cast_roots.is_empty(),
            "fieldless Discriminant must not emit __cast_instance_intrinsic; roots={tag_cast_roots:?}"
        );

        let (_, _, fields, _, _, attrs, _, _) =
            super::derive_program_metadata(&llbc, &gc_struct_ids);
        let closure_key = "fixture::capture::closure";
        let attr_rows = attrs
            .get("capture::closure")
            .or_else(|| attrs.get(closure_key))
            .expect("closure FORCE rows");
        let layout_rows = fields
            .fields
            .get(closure_key)
            .or_else(|| fields.fields.get("capture::closure"))
            .cloned()
            .expect("closure layout rows");
        let layout_pairs: Vec<(String, String)> = layout_rows
            .iter()
            .map(|row| (row.name.clone(), row.ty.clone()))
            .collect();
        assert!(
            fields.fields.contains_key(closure_key),
            "intern keys the full closure path; keys={:?}",
            fields.fields.keys().collect::<Vec<_>>()
        );
        crate::annotator::classdesc::register_struct_fields_with_layout(
            closure_key,
            attr_rows,
            Some(layout_pairs.as_slice()),
        );
        crate::annotator::classdesc::register_struct_fields_with_layout(
            "capture::closure",
            attr_rows,
            Some(layout_pairs.as_slice()),
        );

        let ann = RPythonAnnotator::new(None, None, None, false);
        let bk = &ann.bookkeeper;
        bk.set_struct_fields(Rc::new(fields));
        let registry = CallRegistry::new(bk.clone());
        let lifted = function_graph_to_flowspace(&graph, &registry).expect("lift capture");
        crate::translator::simplify::simplify_graph(&lifted.graph.borrow(), None);
        let start = lifted.graph.borrow().startblock.clone();
        let n_inputs = start.borrow().inputargs.len();
        let cells: Vec<Option<SomeValue>> = (0..n_inputs)
            .map(|_| Some(SomeValue::Integer(SomeInteger::new(true, false))))
            .collect();
        ann.addpendingblock(&lifted.graph, &start, &cells);
        ann.complete_pending_blocks()
            .expect("a closure capturing a fieldless-enum tag annotates");

        let tag_ann = RPythonAnnotator::new(None, None, None, false);
        let tag_bk = &tag_ann.bookkeeper;
        tag_bk.set_struct_fields(Rc::new(
            super::derive_program_metadata(&llbc, &gc_struct_ids).2,
        ));
        let tag_registry = CallRegistry::new(tag_bk.clone());
        let tag_lifted = function_graph_to_flowspace(&tag_graph, &tag_registry).expect("lift tag");
        crate::translator::simplify::simplify_graph(&tag_lifted.graph.borrow(), None);
        let tag_start = tag_lifted.graph.borrow().startblock.clone();
        let tag_n = tag_start.borrow().inputargs.len();
        let tag_cells: Vec<Option<SomeValue>> = (0..tag_n)
            .map(|_| Some(SomeValue::Integer(SomeInteger::new(true, false))))
            .collect();
        tag_ann.addpendingblock(&tag_lifted.graph, &tag_start, &tag_cells);
        tag_ann
            .complete_pending_blocks()
            .expect("Discriminant of a borrowed fieldless-enum tag annotates");
    }

    #[test]
    fn linked_transparent_definition_types_opaque_dependency_view() {
        let type_decl = |kind: serde_json::Value| {
            serde_json::json!({
                "def_id": 1,
                "item_meta": {
                    "name": [{"Ident": ["shared", 0]}, {"Ident": ["Word", 0]}],
                    "span": {"data": {
                        "file_id": 0,
                        "beg": {"line": 1, "col": 0},
                        "end": {"line": 1, "col": 16}
                    }},
                    "source_text": "struct Word(i64);",
                    "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                    "is_local": true
                },
                "kind": kind,
                "layout": [{
                    "key": "x86_64-unknown-linux-gnu",
                    "value": {
                        "size": 8,
                        "align": 8,
                        "variant_layouts": [{"field_offsets": [0]}],
                        "repr": {"repr_algo": "Rust", "transparent": true}
                    }
                }]
            })
        };
        let artifact = |kind| {
            serde_json::json!({
                "charon_version": "0.1.201",
                "has_errors": false,
                "translated": {
                    "crate_name": "fixture",
                    "type_decls": [null, type_decl(kind)],
                    "fun_decls": [],
                    "global_decls": [],
                    "trait_decls": [],
                    "trait_impls": []
                }
            })
        };
        let defining = Llbc::from_slice(
            artifact(serde_json::json!({"Struct": [{
                "name": null,
                "ty": {"Value": [7, {"Scalar": {"Integer": {"Signed": "I64"}}}]},
                "attr_info": null
            }]}))
            .to_string()
            .as_bytes(),
        )
        .unwrap();
        let opaque =
            Llbc::from_slice(artifact(serde_json::json!("Opaque")).to_string().as_bytes()).unwrap();
        let llbcs = vec![defining, opaque];
        super::link_transparent_scalar_types(&llbcs);
        let jitdriver_receiver_roots =
            crate::codewriter::jtransform::default_jitdriver_receiver_roots();
        super::build_semantic_program_from_llbc_with_static_addrs_filtered(
            &llbcs[1],
            crate::HostStaticAddrs::default(),
            &jitdriver_receiver_roots,
            None,
            None,
            super::no_tombstoned_leaves(),
        )
        .unwrap();
        let linked_ty = serde_json::from_value::<super::TyRef>(serde_json::json!({
            "Value": [8, {
                "Adt": {"id": 1, "generics": {"types": []}}
            }]
        }))
        .unwrap();
        assert_eq!(
            super::tyref_to_value_type(&linked_ty, &llbcs[1]),
            crate::model::ValueType::Int
        );
        assert_eq!(
            super::tyref_to_attr_value_type(&linked_ty, &llbcs[1]),
            crate::model::ValueType::Int
        );
        let gc_struct_ids = super::harvest_declared_gc_facts(&llbcs[1]).gc_struct_ids();
        assert_eq!(
            super::tyref_to_field_layout_string(&linked_ty, &llbcs[1], &gc_struct_ids),
            "i64"
        );
    }

    fn ptr_ty() -> serde_json::Value {
        serde_json::json!({"RawPtr": [usize_ty(), "Const"]})
    }

    fn opaque_fun(def_id: u64, path: &[&str]) -> serde_json::Value {
        let ty = ptr_ty();
        serde_json::json!({
            "def_id": def_id,
            "item_meta": item_meta_json(path, "", true),
            "signature": {"is_unsafe": true, "inputs": [ty], "output": ty},
            "body": {"Unstructured": {
                "span": span_json(),
                "locals": {"arg_count": 1, "locals": [
                    {"index": 0, "name": null, "span": span_json(), "ty": ty},
                    {"index": 1, "name": "p", "span": span_json(), "ty": ty}
                ]},
                "body": [{
                    "statements": [],
                    "terminator": {"span": span_json(), "kind": "Return"}
                }]
            }}
        })
    }

    fn chars_offset_global(def_id: u64, leaf: &str) -> serde_json::Value {
        serde_json::json!({
            "def_id": def_id,
            "item_meta": item_meta_json(
                &["pyre_object", "lowlevel_string", leaf],
                "",
                true
            ),
            "global_kind": "NamedConst",
            "ty": usize_ty(),
            "value": {"Value": [0, [{"Call": [{"kind": {"Fun": 0}, "generics": {"regions": [], "types": [], "const_generics": [], "trait_refs": []}}, []]}, usize_ty()]]}
        })
    }

    /// `from_raw_parts((base as *const u8).add(OFFSET), len(base))`.
    /// `len_local` selects which argument the length call peels to.
    fn str_chars_view_fun(offset_leaf: &str, len_local: u64) -> Llbc {
        let ty = ptr_ty();
        let usize_t = usize_ty();
        let cast = |src: u64, dst: u64| {
            serde_json::json!({"Assign": [
                {"kind": {"Local": dst}, "ty": ty},
                {"UnaryOp": [
                    {"Cast": {"RawPtr": [ty, ty]}},
                    {"Move": {"kind": {"Local": src}, "ty": ty}}
                ]}
            ]})
        };
        let copy = |src: u64, dst: u64, slot_ty: serde_json::Value| {
            serde_json::json!({"Assign": [
                {"kind": {"Local": dst}, "ty": slot_ty},
                {"Use": [{"Copy": {"kind": {"Local": src}, "ty": slot_ty}}, "No"]}
            ]})
        };
        let call = |fun: u64,
                    args: serde_json::Value,
                    dest: u64,
                    dest_ty: serde_json::Value,
                    target: u64| {
            serde_json::json!({"Call": {"call": {
                "func": {"Regular": {
                    "kind": {"Fun": fun},
                    "generics": empty_generics()
                }},
                "args": args,
                "dest": {"kind": {"Local": dest}, "ty": dest_ty}
            }, "target": target, "on_unwind": 4}})
        };
        let stmt = |kind: serde_json::Value| serde_json::json!({"span": span_json(), "kind": kind});
        let viewer = serde_json::json!({
            "def_id": 0,
            "item_meta": item_meta_json(
                &["fixture", "not_the_enclosing_name"],
                "",
                true
            ),
            "signature": {"is_unsafe": true, "inputs": [ty, ty], "output": ty},
            "body": {"Unstructured": {
                "span": span_json(),
                "locals": {"arg_count": 2, "locals": [
                    {"index": 0, "name": null, "span": span_json(), "ty": ty},
                    {"index": 1, "name": "base", "span": span_json(), "ty": ty},
                    {"index": 2, "name": "other", "span": span_json(), "ty": ty},
                    {"index": 3, "name": null, "span": span_json(), "ty": ty},
                    {"index": 4, "name": null, "span": span_json(), "ty": ty},
                    {"index": 5, "name": "len", "span": span_json(), "ty": usize_t},
                    {"index": 6, "name": null, "span": span_json(), "ty": ty},
                    {"index": 7, "name": null, "span": span_json(), "ty": ty},
                    {"index": 8, "name": null, "span": span_json(), "ty": ty},
                    {"index": 9, "name": null, "span": span_json(), "ty": usize_t},
                    {"index": 10, "name": null, "span": span_json(), "ty": ty}
                ]},
                "body": [
                    {
                        "statements": [stmt(copy(len_local, 3, ty.clone())), stmt(cast(3, 4))],
                        "terminator": {"span": span_json(), "kind": call(
                            1,
                            serde_json::json!([{"Move": {"kind": {"Local": 4}, "ty": ty}}]),
                            5,
                            usize_t.clone(),
                            1
                        )}
                    },
                    {
                        "statements": [stmt(copy(1, 6, ty.clone())), stmt(cast(6, 7))],
                        "terminator": {"span": span_json(), "kind": call(
                            2,
                            serde_json::json!([
                                {"Move": {"kind": {"Local": 7}, "ty": ty}},
                                {"Copy": {"kind": {"Global": {
                                    "generics": empty_generics(),
                                    "id": 1
                                }}, "ty": usize_t}}
                            ]),
                            8,
                            ty.clone(),
                            2
                        )}
                    },
                    {
                        "statements": [stmt(copy(5, 9, usize_t.clone()))],
                        "terminator": {"span": span_json(), "kind": call(
                            3,
                            serde_json::json!([
                                {"Move": {"kind": {"Local": 8}, "ty": ty}},
                                {"Move": {"kind": {"Local": 9}, "ty": usize_t}}
                            ]),
                            10,
                            ty.clone(),
                            3
                        )}
                    },
                    {
                        "statements": [stmt(serde_json::json!({"Assign": [
                            {"kind": {"Local": 0}, "ty": ty},
                            {"Use": [{"Move": {"kind": {"Local": 10}, "ty": ty}}, "No"]}
                        ]}))],
                        "terminator": {"span": span_json(), "kind": "Return"}
                    },
                    {
                        "statements": [],
                        "terminator": {"span": span_json(), "kind": "UnwindResume"}
                    }
                ]
            }}
        });
        const_artifact(
            "fixture",
            serde_json::json!([
                viewer,
                opaque_fun(
                    1,
                    &["pyre_object", "lowlevel_string", "bh_lowlevel_string_len"]
                ),
                opaque_fun(2, &["core", "ptr", "const_ptr", "<Impl>", "add"]),
                opaque_fun(3, &["core", "slice", "raw", "from_raw_parts"])
            ]),
            serde_json::json!([null, chars_offset_global(1, offset_leaf)]),
        )
    }

    /// A monomorphized vtable keeps its method slots as `*const ()`, so the
    /// `dyn` call casts the slot into a temporary and calls that; the slot
    /// read is recovered from the temporary's single producer.
    #[test]
    fn a_mono_vtable_call_reads_the_slot_under_its_fn_ptr_cast() {
        let ty = ptr_ty();
        let slot = serde_json::json!({"Copy": {"kind": {"Projection": [
            {"kind": {"Projection": [{"kind": {"Local": 1}, "ty": ty}, "Deref"]}, "ty": ty},
            {"Field": [null, 4]}
        ]}, "ty": ty}});
        let assign = |dst: u64, rvalue: serde_json::Value| {
            serde_json::json!({"span": span_json(), "kind": {"Assign": [
                {"kind": {"Local": dst}, "ty": ty},
                rvalue
            ]}})
        };
        let local = |index: u64| serde_json::json!({"index": index, "name": null, "span": span_json(), "ty": ty});
        let fun = serde_json::json!({
            "def_id": 0,
            "item_meta": item_meta_json(&["fixture", "dyn_call"], "", true),
            "signature": {"is_unsafe": true, "inputs": [ty], "output": ty},
            "body": {"Unstructured": {
                "span": span_json(),
                "locals": {"arg_count": 1, "locals": [local(0), local(1), local(2), local(3)]},
                "body": [{
                    "statements": [
                        assign(2, serde_json::json!({"UnaryOp": [
                            {"Cast": {"RawPtr": [ty, ty]}},
                            slot
                        ]})),
                        assign(3, serde_json::json!({"Use": [slot, "No"]}))
                    ],
                    "terminator": {"span": span_json(), "kind": "Return"}
                }]
            }}
        });
        let llbc = const_artifact("fixture", serde_json::json!([fun]), serde_json::json!([]));
        let fd = llbc.iter_local_fns().next().expect("fixture fn");
        let body = fd.unstructured().expect("fixture body");
        let operand = |index: u64| {
            serde_json::from_value::<majit_charon_reader::ullbc::Operand>(serde_json::json!(
                {"Copy": {"kind": {"Local": index}, "ty": ty}}
            ))
            .unwrap()
        };
        let peeled = super::vtable_slot_under_fn_ptr_cast(&llbc, &body, &operand(2))
            .expect("the cast temporary names its vtable slot");
        let expected =
            serde_json::from_value::<majit_charon_reader::ullbc::Operand>(slot.clone()).unwrap();
        assert_eq!(format!("{peeled:?}"), format!("{expected:?}"));
        assert!(
            super::vtable_slot_under_fn_ptr_cast(&llbc, &body, &operand(3)).is_none(),
            "a plain copy of the slot is not a cast temporary"
        );
    }

    fn graph_calls_leaf(graph: &crate::model::FunctionGraph, leaf: &str) -> bool {
        graph.blocks.iter().flat_map(|block| &block.operations).any(|op| {
            matches!(
                &op.kind,
                OpKind::Call { target: crate::model::CallTarget::FunctionPath { segments, .. }, .. }
                    if segments.last().is_some_and(|seg| seg == leaf)
            )
        })
    }

    #[test]
    fn str_chars_view_from_raw_parts_aliases_same_base() {
        let llbc = str_chars_view_fun("LOWLEVEL_STRING_CHARS_OFFSET", 1);
        let graph = super::lower_function(&llbc, "fixture::not_the_enclosing_name")
            .expect("chars view lowers");
        assert!(
            !graph_calls_leaf(&graph, "from_raw_parts"),
            "same-base chars view must alias the STR, graph: {graph:#?}"
        );
        let returned = graph.blocks.iter().find_map(|block| {
            block.exits.iter().find_map(|exit| {
                (exit.target == graph.returnblock).then(|| {
                    exit.args.iter().find_map(|arg| match arg {
                        crate::model::LinkArg::Value(var) => Some(var.id()),
                        _ => None,
                    })
                })?
            })
        });
        let input_id = graph
            .blocks
            .first()
            .and_then(|block| block.inputargs.first())
            .map(|var| var.id());
        let returned_id = returned.expect("the chars view returns a value");
        let input_id = input_id.expect("the STR base is a block argument");
        let threaded = graph.blocks.iter().any(|block| {
            block.exits.iter().any(|exit| {
                exit.args.iter().any(
                    |arg| matches!(arg, crate::model::LinkArg::Value(var) if var.id() == input_id),
                ) && graph.blocks.iter().any(|target| {
                    target.id == exit.target
                        && target.inputargs.iter().any(|arg| arg.id() == returned_id)
                })
            })
        }) || returned_id == input_id;
        assert!(
            threaded,
            "the slice destination must be the STR base (input {input_id}, return {returned_id})"
        );
    }

    #[test]
    fn str_chars_view_from_raw_parts_keeps_other_shapes() {
        let other_offset = str_chars_view_fun("LOWLEVEL_STR_BASE_SIZE", 1);
        let graph = super::lower_function(&other_offset, "fixture::not_the_enclosing_name")
            .expect("other offset still lowers");
        assert!(
            graph_calls_leaf(&graph, "from_raw_parts"),
            "a different offset must not drop its length"
        );
        let other_base = str_chars_view_fun("LOWLEVEL_STRING_CHARS_OFFSET", 2);
        let graph = super::lower_function(&other_base, "fixture::not_the_enclosing_name")
            .expect("different base still lowers");
        assert!(
            graph_calls_leaf(&graph, "from_raw_parts"),
            "a length from a different base must not drop n"
        );
    }

    /// `p.add/sub(LOWLEVEL_STRING_CHARS_OFFSET)` with no string-header peel.
