    /// Real-LLBC anchor for the unsigned `saturating_sub` clamp diamond:
    /// `generic_alias_class_getitem`'s arg-count error path computes
    /// `args.len().saturating_sub(1)`.  `core::intrinsics::saturating_sub`
    /// (`rint.py` `rtype_sub_ovf` for signed; unsigned floors at zero) is
    /// mapped in `lower_call`.  There must be no residual
    /// `["num","<Impl>","saturating_sub"]` call and at least one `lt` guard
    /// + one `sub` (the `if a < b { 0 } else { a - b }` diamond).  `#[ignore]`d
    /// (loads the ~440MB real LLBC); run with
    /// `cargo test -p majit-translate --lib saturating_sub_generic_alias_real
    /// -- --ignored`.
    #[test]
    #[ignore]
    fn saturating_sub_generic_alias_real() {
        use crate::model::{CallTarget, OpKind};
        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph = super::lower_function(&llbc, "generic_alias_class_getitem")
            .expect("lower generic_alias_class_getitem");
        let residual = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                        if super::fmt_path_ends_with(segments, &["num", "<Impl>", "saturating_sub"])
                )
            })
            .count();
        assert_eq!(
            residual, 0,
            "generic_alias_class_getitem: residual saturating_sub after the clamp-diamond rewrite"
        );
        let lt_guards = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| matches!(&op.kind, OpKind::BinOp { op, .. } if op == "lt"))
            .count();
        let subs = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| matches!(&op.kind, OpKind::BinOp { op, .. } if op == "sub"))
            .count();
        assert!(
            lt_guards >= 1 && subs >= 1,
            "generic_alias_class_getitem: expected the a<b guard and the a-b subtraction \
             (lt={lt_guards}, sub={subs})"
        );
    }

    /// Real-LLBC anchor for the unsigned `saturating_sub` wrapper itself.
    /// In-lowering rewrite of `core::intrinsics::saturating_sub` replaced
    /// the Call's goto with non-MIR diamond arms, so `lower_framestate`
    /// `stub_dead_block`'d the Return continuation (`flowcontext.py`
    /// `make_next_block`) and the wrapper became a raise-only stub. The
    /// clamp rewrite now runs after the body lowers (`bool::then` /
    /// `saturating_mul`); the usize wrapper must keep the `lt`/`sub`
    /// diamond and must not close startblock onto exceptblock.
    /// `#[ignore]`d (loads the object LLBC); run with
    /// `cargo test -p majit-translate --lib saturating_sub_wrapper_diamond_real
    /// -- --ignored`.
    #[test]
    #[ignore]
    fn saturating_sub_wrapper_diamond_real() {
        use crate::model::OpKind;
        let path = crate::runtime_names::artifacts::OBJECT_ULLBC;
        let llbc = Llbc::load(path).expect("load object LLBC");
        let context = super::LowerContext::new(&llbc);
        let mut saw = 0usize;
        for fd in llbc.iter_fun_decls() {
            if fd.item_meta.name_path() != "core::num::<Impl>::saturating_sub" {
                continue;
            }
            if !fd.has_unstructured_body() {
                continue;
            }
            let graph = super::lower_fun_decl(&context, fd)
                .expect("lower core::num::<Impl>::saturating_sub");
            let start = &graph.blocks[graph.startblock.0];
            assert!(
                !(start.exits.len() == 1 && start.exits[0].target == graph.exceptblock),
                "{}: startblock is a raise-only stub (framestate stub_dead_block of the Return continuation)",
                graph.name
            );
            let lt_guards = graph
                .blocks
                .iter()
                .flat_map(|b| b.operations.iter())
                .filter(|op| matches!(&op.kind, OpKind::BinOp { op, .. } if op == "lt"))
                .count();
            let subs = graph
                .blocks
                .iter()
                .flat_map(|b| b.operations.iter())
                .filter(|op| matches!(&op.kind, OpKind::BinOp { op, .. } if op == "sub"))
                .count();
            assert!(
                lt_guards >= 1 && subs >= 1,
                "{}: expected the unsigned clamp diamond (lt={lt_guards}, sub={subs})",
                graph.name
            );
            saw += 1;
        }
        assert!(
            saw >= 1,
            "object LLBC: expected at least one unstructured core::num::<Impl>::saturating_sub"
        );
    }

    /// Real-LLBC anchor for the `Option::is_some_and` closure-select fold:
    /// `is_mmap` is `type(obj).is_some_and(|tp| ptr::eq(tp.as_ptr(),
    /// mmap_type()))`.  After the `option_closure_select` post-pass there must
    /// be no residual `is_some_and` `Method` call, and block A must branch two
    /// ways (the `Some`/`None` discriminant diamond).  `#[ignore]`d (loads the
    /// ~440MB real LLBC); run with `cargo test -p majit-translate --lib
    /// is_some_and_is_mmap_real -- --ignored`.
    #[test]
    #[ignore]
    fn is_some_and_is_mmap_real() {
        use crate::model::{CallTarget, OpKind};
        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph = super::lower_function(&llbc, "is_mmap").expect("lower is_mmap");
        let residual = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call { target: CallTarget::Method { name, .. }, .. }
                        if name == "is_some_and"
                )
            })
            .count();
        assert_eq!(
            residual, 0,
            "is_mmap: residual is_some_and call after the closure-select rewrite"
        );
        let branching = graph.blocks.iter().filter(|b| b.exits.len() == 2).count();
        assert!(
            branching >= 1,
            "is_mmap: expected the Some/None discriminant branch (a 2-exit block)"
        );
    }

    /// Real-LLBC anchor for the `FixedObjectArray::set_ref` setarrayitem
    /// collapse: `set_locals_w` (the shared STORE_FAST-family leaf) calls
    /// `self.locals_cells_stack_w.set_ref(index, value)`.  After the
    /// whole-method lift there must be no residual
    /// `["object_array","<Impl>","set_ref"]` call and no residual
    /// `items_mut_ptr` / write-barrier accessor from the method body, and at
    /// least one native `ArrayWrite` (the `setarrayitem_gc`).  `#[ignore]`d
    /// (loads the ~440MB real LLBC); run with `cargo test -p majit-translate
    /// --lib set_ref_set_locals_w_real -- --ignored`.
    #[test]
    #[ignore]
    fn set_ref_set_locals_w_real() {
        use crate::model::{CallTarget, OpKind};
        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph = super::lower_function(&llbc, "set_locals_w").expect("lower set_locals_w");
        let value_input_root = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .find_map(|op| match &op.kind {
                OpKind::Input {
                    name, class_root, ..
                } if name == "value" => class_root.as_deref(),
                _ => None,
            });
        assert_eq!(
            value_input_root,
            Some("PyObject"),
            "PyObjectRef input must retain the W_Root-equivalent class identity"
        );
        let residual = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                        if super::fmt_path_ends_with(segments, &["object_array", "<Impl>", "set_ref"])
                )
            })
            .count();
        assert_eq!(
            residual, 0,
            "set_locals_w: residual set_ref call after the setarrayitem collapse"
        );
        let array_writes = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| matches!(&op.kind, OpKind::ArrayWrite { .. }))
            .count();
        assert!(
            array_writes >= 1,
            "set_locals_w: expected at least one native ArrayWrite (setarrayitem_gc)"
        );
        let typed_store = graph.blocks.iter().any(|block| {
            block.operations.windows(2).any(|ops| {
                let Some(cast_result) = ops[0].result.as_ref() else {
                    return false;
                };
                crate::model::cast_instance_root(&ops[0].kind) == Some("PyObject") && matches!(
                    &ops[1].kind,
                    OpKind::ArrayWrite {
                        value: crate::model::LinkArg::Value(value),
                        array_type_id: Some(array_type_id),
                        ..
                    } if value == cast_result && array_type_id == super::OBJECT_REF_GCARRAY_TYPE_ID
                )
            })
        });
        assert!(
            typed_store,
            "set_locals_w: PyObjectRef store must preserve the W_Root external item repr"
        );
    }

    /// PyPy's frame stack clears store `None` into a `W_Root` list.  The Rust
    /// sentinel `PY_NULL` must therefore retain the `PyObject` class boundary
    /// while becoming nullable; a classdef-less null would widen the shared
    /// `FixedObjectArray` item to the erased top reference.
    #[test]
    #[ignore]
    fn popvalue_py_null_narrows_to_nullable_instance() {
        use crate::model::OpKind;
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../build/llbc/pyre-interpreter.ullbc"
        );
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph = super::lower_function(
            &llbc,
            "pyre_interpreter::pyframe::<Impl>::popvalue_maybe_none",
        )
        .expect("lower PyFrame::popvalue_maybe_none");
        let has_nullable_instance = graph.blocks.iter().any(|block| {
            block.operations.windows(2).any(|ops| {
                matches!(
                    &ops[0].kind,
                    OpKind::Call { target, .. } if target.to_string() == "core::ptr::null_mut"
                ) && crate::model::cast_instance_root(&ops[1].kind) == Some("PyObject")
            })
        });
        assert!(
            has_nullable_instance,
            "PY_NULL stack clear must lower as null_mut followed by a PyObject narrow"
        );
    }

    /// `call_method`'s `Result<Option<PyObjectRef>, PyError>::Ok.__pos_0`
    /// is the niche pointer. The read must narrow to nullable `PyObject`
    /// before it merges with the `PY_NULL` arm.
    #[test]
    #[ignore]
    fn call_method_ok_payload_narrows_to_the_instance_class() {
        use crate::model::OpKind;
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../build/llbc/pyre-interpreter.ullbc"
        );
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph = super::lower_function(&llbc, "pyre_interpreter::baseobjspace::call_method")
            .expect("lower call_method");
        let narrowed = graph.blocks.iter().any(|block| {
            block.operations.windows(2).any(|ops| {
                let OpKind::FieldRead { field, .. } = &ops[0].kind else {
                    return false;
                };
                field.name == "__pos_0"
                    && field
                        .owner_root
                        .as_deref()
                        .is_some_and(|owner| owner.contains("Result") && owner.contains("PyObject"))
                    && crate::model::cast_instance_root(&ops[1].kind) == Some("PyObject")
            })
        });
        assert!(
            narrowed,
            "call_method Ok payload read must be followed by a PyObject narrow"
        );
    }

    /// Real-LLBC anchor for the `we_are_jitted()` → `ConstBool(true)` front
    /// fold: `lookup_in_type_where` branches on `if not we_are_jitted()` and,
    /// in the interpreter arm, calls `_cached_lookup_where_name`, whose body
    /// reads the residual-only `METHOD_CACHE` static.  After the front fold the
    /// interpreter arm is JIT-dead and the annotator prunes it, but the fold
    /// itself already removes the `we_are_jitted` call and collapses its
    /// two-way branch to the JIT arm's unconditional goto — so the lowered
    /// graph carries no `we_are_jitted` call.  `#[ignore]`d (loads the ~440MB
    /// real LLBC); run with `cargo test -p majit-translate --lib
    /// we_are_jitted_lookup_in_type_where_real -- --ignored`.
    #[test]
    #[ignore]
    fn we_are_jitted_lookup_in_type_where_real() {
        use crate::model::{CallTarget, OpKind};
        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph = super::lower_function(&llbc, "lookup_in_type_where")
            .expect("lower lookup_in_type_where");
        let we_are_jitted_residual = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                        if super::fmt_path_ends_with(segments, &["jit", "we_are_jitted"])
                )
            })
            .count();
        assert_eq!(
            we_are_jitted_residual, 0,
            "lookup_in_type_where: residual we_are_jitted call after the front fold"
        );
        // The interpreter arm's `_cached_lookup_where_name` call (which reads
        // the residual-only `METHOD_CACHE` static) is JIT-dead once
        // `we_are_jitted()` folds to True.  The front fold collapses the branch
        // to the JIT arm's unconditional goto, so the interpreter arm becomes
        // unreachable and `simplify_lowered_graph`'s `clear_unreachable_blocks`
        // empties its operations — no `_cached_lookup_where_name` call survives.
        let cached_lookup_residual = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                        if super::fmt_path_ends_with(segments, &["baseobjspace", "_cached_lookup_where_name"])
                )
            })
            .count();
        assert_eq!(
            cached_lookup_residual, 0,
            "lookup_in_type_where: residual _cached_lookup_where_name (METHOD_CACHE reader) \
             after the we_are_jitted fold pruned the interpreter arm"
        );
    }

    /// Real-LLBC anchor for the fieldless-enum `Debug` `format!` collapse:
    /// `call_intrinsic_1`'s unknown-intrinsic arm renders `func`
    /// (`IntrinsicFunction1`, a fieldless enum) with `{:?}`, which lowers to
    /// the `alloc::fmt::format` / `fmt::rt::Argument::new_debug` chain.  After
    /// `collapse_debug_enum_fmt_chains` there must be no residual `new_debug`
    /// (the graph-less extern that walls the rtyper) and the enum-discriminant
    /// switch must be present.  `#[ignore]`d (loads the ~440MB real LLBC); run
    /// with `cargo test -p majit-translate --lib call_intrinsic_1_debug_enum_fmt_real
    /// -- --ignored`.
    #[test]
    #[ignore]
    fn call_intrinsic_1_debug_enum_fmt_real() {
        use crate::model::{CallTarget, ExitSwitch, OpKind};
        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph =
            super::lower_function(&llbc, "call_intrinsic_1").expect("lower call_intrinsic_1");
        let new_debug_residual = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                        if super::fmt_path_ends_with(segments, &["Argument", "new_debug"])
                )
            })
            .count();
        assert_eq!(
            new_debug_residual, 0,
            "call_intrinsic_1: residual fmt::rt::Argument::new_debug after the Debug-enum collapse"
        );
        let has_value_switch = graph
            .blocks
            .iter()
            .any(|b| matches!(b.exitswitch, Some(ExitSwitch::Value(_))));
        assert!(
            has_value_switch,
            "call_intrinsic_1: expected an enum-discriminant switch after the collapse"
        );
    }

    /// Re-type the small checked-in `option_source` graph with a chosen
    /// payload and lower it. This preserves the exact Charon constructor CFG
    /// used by the existing corpus harness while avoiding a large real-LLBC
    /// load. The function has one `Some(value)` arm and one niladic `None`
    /// arm, so the resulting graph directly exposes whether the classifier
    /// chose aggregate construction or the nullable-pointer identities.
    fn lower_option_source_with_payload(payload: serde_json::Value) -> FunctionGraph {
        lower_option_fn_retyped("option_source", payload, false, false, false)
    }

    fn lower_option_source_with_payload_ext(
        payload: serde_json::Value,
        inject_layoutless_nominal: bool,
    ) -> FunctionGraph {
        lower_option_fn_retyped(
            "option_source",
            payload,
            false,
            inject_layoutless_nominal,
            false,
        )
    }

    fn lower_option_source_with_aliased_payload(payload: serde_json::Value) -> FunctionGraph {
        lower_option_fn_retyped("option_source", payload, true, false, false)
    }

    fn lower_option_fn_retyped(
        fn_name: &str,
        mut payload: serde_json::Value,
        through_alias: bool,
        inject_layoutless_nominal: bool,
        inject_string: bool,
    ) -> FunctionGraph {
        fn replace_dedup(
            value: &mut serde_json::Value,
            payload_id: u64,
            output_id: u64,
            payload: &serde_json::Value,
            option_ty: &serde_json::Value,
        ) {
            if let Some(id) = value
                .as_object()
                .and_then(|obj| obj.get("Deduplicated"))
                .and_then(serde_json::Value::as_u64)
            {
                if id == payload_id {
                    *value = payload.clone();
                } else if id == output_id {
                    *value = option_ty.clone();
                }
                return;
            }
            match value {
                serde_json::Value::Array(values) => {
                    for value in values {
                        replace_dedup(value, payload_id, output_id, payload, option_ty);
                    }
                }
                serde_json::Value::Object(values) => {
                    for value in values.values_mut() {
                        replace_dedup(value, payload_id, output_id, payload, option_ty);
                    }
                }
                _ => {}
            }
        }

        let path = crate::runtime_names::artifacts::CHARON_CORPUS_ULLBC;
        let bytes = std::fs::read(path).expect("read checked-in corpus LLBC");
        let mut file: serde_json::Value =
            serde_json::from_slice(&bytes).expect("parse checked-in corpus JSON");
        let translated = file
            .get_mut("translated")
            .and_then(serde_json::Value::as_object_mut)
            .expect("corpus translated object");

        if through_alias {
            let decls = translated
                .get_mut("type_decls")
                .and_then(serde_json::Value::as_array_mut)
                .expect("corpus type_decls");
            // Charon `type_by_id` indexes the table by position, so the
            // alias id is the slot this push occupies, not max(def_id)+1.
            let alias_id = decls.len() as u64;
            let template = decls
                .iter()
                .find(|decl| {
                    decl.get("kind")
                        .and_then(|kind| kind.get("Alias"))
                        .is_some()
                })
                .cloned()
                .expect("corpus has a type alias to copy item_meta from");
            let mut alias_decl = template;
            alias_decl
                .as_object_mut()
                .expect("type decl object")
                .insert("def_id".to_string(), serde_json::json!(alias_id));
            alias_decl
                .as_object_mut()
                .expect("type decl object")
                .insert(
                    "kind".to_string(),
                    serde_json::json!({ "Alias": payload.clone() }),
                );
            if let Some(meta) = alias_decl
                .get_mut("item_meta")
                .and_then(|m| m.as_object_mut())
            {
                meta.insert(
                    "name".to_string(),
                    serde_json::json!([
                        {"Ident": ["charon_corpus", 0]},
                        {"Ident": ["ObjectPtr", 0]}
                    ]),
                );
            }
            decls.push(alias_decl);
            payload = serde_json::json!({
                "Adt": {
                    "id": alias_id,
                    "generics": {
                        "regions": [],
                        "types": [],
                        "const_generics": [],
                        "trait_refs": []
                    }
                }
            });
        }

        let option_def_id = translated
            .get("type_decls")
            .and_then(serde_json::Value::as_array)
            .and_then(|decls| {
                decls.iter().find_map(|decl| {
                    let names = decl.get("item_meta")?.get("name")?.as_array()?;
                    let path: Vec<&str> = names
                        .iter()
                        .filter_map(|seg| seg.get("Ident")?.get(0)?.as_str())
                        .collect();
                    (path.as_slice() == ["core", "option", "Option"])
                        .then(|| decl.get("def_id")?.as_u64())?
                })
            })
            .expect("Option type declaration in corpus");
        if inject_layoutless_nominal {
            let decls = translated
                .get_mut("type_decls")
                .and_then(serde_json::Value::as_array_mut)
                .expect("corpus type_decls");
            // `type_by_id` indexes this array by `def_id`. A hole is the
            // only free index a copy can occupy.
            let hole = decls
                .iter()
                .position(serde_json::Value::is_null)
                .expect("corpus type_decls has a null hole");
            let mut copy = decls
                .iter()
                .find(|decl| decl.get("def_id").and_then(serde_json::Value::as_u64) == Some(4))
                .expect("sized nominal def-id 4")
                .clone();
            copy["def_id"] = serde_json::json!(hole);
            copy.as_object_mut()
                .expect("type decl object")
                .remove("layout");
            decls[hole] = copy;
            // The fixture payload names Adt 1000 as the stand-in. Point it
            // at the hole the copy actually occupies.
            fn retarget(value: &mut serde_json::Value, hole: u64) {
                if value.get("id").and_then(serde_json::Value::as_u64) == Some(1000) {
                    value["id"] = serde_json::json!(hole);
                }
                match value {
                    serde_json::Value::Array(items) => {
                        for item in items {
                            retarget(item, hole);
                        }
                    }
                    serde_json::Value::Object(map) => {
                        for item in map.values_mut() {
                            retarget(item, hole);
                        }
                    }
                    _ => {}
                }
            }
            retarget(&mut payload, hole as u64);
        }
        if inject_string {
            let decls = translated
                .get_mut("type_decls")
                .and_then(serde_json::Value::as_array_mut)
                .expect("corpus type_decls");
            let hole = decls
                .iter()
                .position(serde_json::Value::is_null)
                .expect("corpus type_decls has a null hole");
            // `SomeRawStruct` is a sized nominal struct; rename the copy to
            // `alloc::string::String` so [`node_is_string_value`] admits it.
            let mut copy = decls
                .iter()
                .find(|decl| decl.get("def_id").and_then(serde_json::Value::as_u64) == Some(5))
                .expect("sized nominal def-id 5")
                .clone();
            copy["def_id"] = serde_json::json!(hole);
            if let Some(meta) = copy.get_mut("item_meta").and_then(|m| m.as_object_mut()) {
                meta.insert(
                    "name".to_string(),
                    serde_json::json!([
                        {"Ident": ["alloc", 0]},
                        {"Ident": ["string", 0]},
                        {"Ident": ["String", 0]}
                    ]),
                );
            }
            decls[hole] = copy;
            payload = serde_json::json!({
                "Adt": {
                    "id": hole,
                    "generics": {
                        "regions": [],
                        "types": [],
                        "const_generics": [],
                        "trait_refs": []
                    }
                }
            });
        }

        let fun = translated
            .get_mut("fun_decls")
            .and_then(serde_json::Value::as_array_mut)
            .and_then(|decls| {
                decls.iter_mut().find(|decl| {
                    decl.get("item_meta")
                        .and_then(|meta| meta.get("name"))
                        .and_then(serde_json::Value::as_array)
                        .and_then(|names| names.last())
                        .and_then(|seg| seg.get("Ident"))
                        .and_then(|ident| ident.get(0))
                        .and_then(serde_json::Value::as_str)
                        == Some(fn_name)
                })
            })
            .unwrap_or_else(|| panic!("{fn_name} declaration in corpus"));
        let signature = fun
            .get("signature")
            .and_then(serde_json::Value::as_object)
            .unwrap_or_else(|| panic!("{fn_name} signature"));
        let payload_id = signature
            .get("inputs")
            .and_then(serde_json::Value::as_array)
            .and_then(|inputs| inputs.get(1))
            .and_then(|ty| ty.get("Deduplicated"))
            .and_then(serde_json::Value::as_u64)
            .unwrap_or_else(|| panic!("{fn_name} payload dedup id"));
        let output_id = signature
            .get("output")
            .and_then(|ty| ty.get("Deduplicated"))
            .and_then(serde_json::Value::as_u64)
            .unwrap_or_else(|| panic!("{fn_name} output dedup id"));
        let option_ty = serde_json::json!({
            "Adt": {
                "id": option_def_id ,
                "generics": {
                    "regions": [],
                    "types": [payload.clone()],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        });
        replace_dedup(fun, payload_id, output_id, &payload, &option_ty);

        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
        super::lower_function(&llbc, fn_name)
            .unwrap_or_else(|e| panic!("lower retyped {fn_name}: {e}"))
    }

    fn niche_ctor_shape(graph: &FunctionGraph) -> (usize, usize) {
        let ops = graph.blocks.iter().flat_map(|block| &block.operations);
        // `rnone.py` `rtype_is_None`: a GC Ptr None is `null_mut` (ref
        // bank); `Option<fn>` is `null_fn` and a raw-address niche is
        // `null_raw` (int bank).
        let nulls = ops
            .clone()
            .filter(|op| {
                matches!(&op.kind, OpKind::Call { target, .. }
                if matches!(
                    target.to_string().as_str(),
                    "core::ptr::null_mut" | "core::ptr::null_fn" | "core::ptr::null_raw"
                ))
            })
            .count();
        let transparent_ctors = ops
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call {
                        target: CallTarget::SyntheticTransparentCtor { .. },
                        ..
                    }
                )
            })
            .count();
        (nulls, transparent_ctors)
    }

    #[test]
    fn niche_option_raw_nominal_ptr_without_layout_is_null_test() {
        use crate::model::OpKind;
        // Cross-crate pointees often have a type decl and no `layout`
        // entry. `Option<*mut That>` is still the nullable pointer:
        // `None` is null and the discriminant is a null test, not a
        // `__discriminant` load of the pointee header.
        let payload = serde_json::json!({
            "RawPtr": [
                {
                    "Adt": {
                        "id": 1000 ,
                        "generics": {
                            "regions": [], "types": [],
                            "const_generics": [], "trait_refs": []
                        }
                    }
                },
                "Mut"
            ]
        });
        let graph = lower_option_source_with_payload_ext(payload, true);
        let (null_muts, transparent_ctors) = niche_ctor_shape(&graph);
        assert_eq!(null_muts, 1, "None must lower to one null pointer");
        assert_eq!(transparent_ctors, 0, "Some must be the pointer identity");
        let discriminant_reads = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(&op.kind, OpKind::FieldRead { field, .. } if field.name == "__discriminant")
            })
            .count();
        assert_eq!(
            discriminant_reads, 0,
            "a layout-less nominal raw pointer must not read __discriminant"
        );
    }

    #[test]
    fn niche_option_type_alias_of_raw_nominal_ptr_none_is_null() {
        use crate::model::OpKind;
        // `type ObjectPtr = *mut HostRegistry` is the Charon spelling of
        // `type PyObjectRef = *mut PyObject`: the Option payload names the
        // alias Adt, not the `RawPtr`.  Discriminant / Some / None must
        // still see one nullable pointer word.
        let payload = serde_json::json!({
            "RawPtr": [
                {
                    "Adt": {
                        "id": 4,
                        "generics": {
                            "regions": [], "types": [],
                            "const_generics": [], "trait_refs": []
                        }
                    }
                },
                "Mut"
            ]
        });
        let graph = lower_option_source_with_aliased_payload(payload);
        let (null_muts, transparent_ctors) = niche_ctor_shape(&graph);
        assert_eq!(
            null_muts, 1,
            "None of an alias-to-raw-nominal-ptr Option must lower to one null pointer"
        );
        assert_eq!(
            transparent_ctors, 0,
            "Some of an alias-to-raw-nominal-ptr Option must be the payload identity"
        );
        let discriminant_reads = graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::FieldRead { field, .. } if field.name == "__discriminant"
                )
            })
            .count();
        assert_eq!(
            discriminant_reads, 0,
            "a pointer-niche Option must not read an aggregate __discriminant"
        );
    }

    #[test]
    fn niche_option_nominal_pointers_none_is_null_some_is_identity() {
        let corpus = Llbc::load(crate::runtime_names::artifacts::CHARON_CORPUS_ULLBC)
            .expect("load checked-in corpus LLBC");
        let box_def_id = corpus
            .iter_type_decls()
            .find(|td| td.item_meta.name_path() == "alloc::boxed::Box")
            .map(|td| td.def_id)
            .expect("Box type declaration in corpus");
        let raw_nominal = serde_json::json!({
            "RawPtr": [
                {
                    "Adt": {
                        "id": 4 ,
                        "generics": {
                            "regions": [], "types": [],
                            "const_generics": [], "trait_refs": []
                        }
                    }
                },
                "Mut"
            ]
        });
        let boxed = serde_json::json!({
            "Adt": {
                "id": box_def_id ,
                "generics": {
                    "regions": [],
                    "types": [{
                        "Adt": {
                            "id": 4 ,
                            "generics": {
                                "regions": [], "types": [],
                                "const_generics": [], "trait_refs": []
                            }
                        }
                    }],
                    "const_generics": [], "trait_refs": []
                }
            }
        });
        let cases = [
            (
                "raw_nominal_ptr",
                raw_nominal,
                "None must lower to one null pointer",
                "Some(raw nominal pointer) must be the payload identity, with no Option aggregate",
            ),
            (
                "boxed_nominal",
                boxed,
                "None must lower to one null owning pointer",
                "Some(Box<nominal>) must be the payload identity, with no Option aggregate",
            ),
        ];
        for (name, payload, none_msg, some_msg) in cases {
            let graph = lower_option_source_with_payload(payload);
            let (null_muts, transparent_ctors) = niche_ctor_shape(&graph);
            assert_eq!(null_muts, 1, "case {name}: {none_msg}");
            assert_eq!(transparent_ctors, 0, "case {name}: {some_msg}");
        }
    }

    /// Real-LLBC anchor for the `FixedObjectArray` Index intercept.  The
    /// intercept returns before `lower_call`'s ordinary result-narrowing tail,
    /// so an object element must carry its own `PyObject` narrow immediately
    /// after the lifted ArrayRead.  Ignored by default because it loads the
    /// large interpreter snapshot.
    #[test]
    #[ignore]
    fn load_local_value_arrayread_narrows_instance_item() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../build/llbc/pyre-interpreter.ullbc"
        );
        let llbc = Llbc::load(path).expect("load real interpreter LLBC");
        let graph =
            super::lower_function(&llbc, "pyre_interpreter::eval::<Impl>::load_local_value")
                .expect("lower eval::<Impl>::load_local_value");
        let has_instance_narrow = graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
            matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } if crate::model::cast_instance_root(&op.kind)
                    .is_some_and(|root| root.ends_with("PyObject"))
            )
        });
        assert!(
            has_instance_narrow,
            "FixedObjectArray getitem must recast its GCREF item to PyObject"
        );
    }

    /// A translated opcode helper is a PyPy frame method, not a generic
    /// classdef-less reference.  Its receiver is the per-frame red argument
    /// that owns `pycode`, globals, and locals, so the front must retain the
    /// concrete `PyFrame` root on the corresponding Input operation.
    #[test]
    #[ignore]
    fn opcode_impl_receiver_keeps_pyframe_input_root() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../build/llbc/pyre-interpreter.ullbc"
        );
        let llbc = Llbc::load(path).expect("load real interpreter LLBC");
        let graph = super::lower_function(&llbc, "pyre_interpreter::eval::<Impl>::pop_value")
            .expect("lower eval::<Impl>::pop_value");
        let receiver = graph
            .block(graph.startblock)
            .operations
            .iter()
            .find_map(|op| match &op.kind {
                OpKind::Input { class_root, .. }
                    if op.result.as_ref() == graph.block(graph.startblock).inputargs.first() =>
                {
                    class_root.as_deref()
                }
                _ => None,
            });
        assert_eq!(
            receiver,
            Some("PyFrame"),
            "opcode impl receiver must retain the concrete per-frame red identity"
        );

        let program =
            super::build_semantic_program_from_llbcs_with_static_addrs_and_function_names(
                &[llbc],
                crate::HostStaticAddrs::default(),
                &[],
                &["pop_value", "pop_top", "build_list", "opcode_build_list"],
            )
            .expect("build filtered opcode program");
        let pyframe_roots: Vec<_> = program
            .struct_fields
            .fields
            .keys()
            .filter(|root| root.rsplit("::").next() == Some("PyFrame"))
            .cloned()
            .collect();
        assert!(
            pyframe_roots.len() > 1,
            "fixture must exercise more than one lookup spelling"
        );
        let mut pyframe_ids: Vec<_> = pyframe_roots
            .iter()
            .map(|root| {
                program
                    .struct_ids
                    .get(root)
                    .copied()
                    .flatten()
                    .expect("every qualified PyFrame alias has an identity")
            })
            .collect();
        pyframe_ids.sort();
        pyframe_ids.dedup();
        assert_eq!(
            pyframe_ids.len(),
            1,
            "all PyFrame lookup spellings must name one class identity"
        );

        let mut trait_impl_owners = crate::TraitImplOwners::new();
        for function in &program.functions {
            let (Some(trait_qualified), Some(owner)) =
                (&function.trait_qualified, &function.self_ty_root)
            else {
                continue;
            };
            trait_impl_owners
                .entry(trait_qualified.clone())
                .or_default()
                .insert(owner.clone());
        }
        let unique_impls = crate::unique_trait_impl_roots(&program, trait_impl_owners);
        let frame_owner = unique_impls
            .iter()
            .find(|(trait_name, _)| trait_name.ends_with("::OpcodeStepExecutor"))
            .map(|(_, owner)| owner)
            .expect("OpcodeStepExecutor has one concrete owner");
        assert!(
            frame_owner.ends_with("::PyFrame"),
            "the production unique-impl census must preserve the qualified frame owner: \
             {frame_owner:?}"
        );
        assert_eq!(
            program.struct_ids.get(frame_owner).copied().flatten(),
            Some(pyframe_ids[0]),
            "the retained owner spelling must resolve to the frame's StructId"
        );
    }

    /// `[OpcodeStepExecutor, to_bool]` on the real interpreter LLBC is the
    /// `PyFrame` override.  The census printed in a failure names which
    /// uniqueness miss is live: several owner strings of one StructId, a
    /// missing override row, or a direct path that stayed the trait default.
    #[test]
    #[ignore]
    fn opcode_step_executor_to_bool_direct_path_is_pyframe_override() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../build/llbc/pyre-interpreter.ullbc"
        );
        let llbc = Llbc::load(path).expect("load real interpreter LLBC");
        let mut owners = std::collections::BTreeSet::new();
        let mut to_bool_override = false;
        let mut to_bool_default = false;
        for fd in llbc.iter_local_fns() {
            let name_path = fd.item_meta.name_path();
            let trait_path = super::trait_impl_trait_path_for_fundecl(&llbc, fd);
            let trait_leaf = trait_path.as_deref().and_then(|p| p.rsplit("::").next());
            if trait_leaf == Some("OpcodeStepExecutor")
                && let Some((owner, method)) = super::impl_method_owner_for_fundecl(&llbc, fd)
            {
                owners.insert(owner);
                if method == "to_bool" {
                    to_bool_override = true;
                }
            }
            if name_path.ends_with("::OpcodeStepExecutor::to_bool") {
                to_bool_default = true;
            }
        }
        let program =
            super::build_semantic_program_from_llbcs_with_static_addrs_and_function_names(
                std::slice::from_ref(&llbc),
                crate::HostStaticAddrs::default(),
                &[],
                &["to_bool"],
            )
            .expect("build filtered to_bool program");
        let mut ids = Vec::new();
        for owner in &owners {
            let id = program
                .struct_ids
                .get(owner)
                .copied()
                .flatten()
                .unwrap_or_else(|| majit_ir::descr::StructId::from_canonical(owner));
            if !ids.contains(&id) {
                ids.push(id);
            }
        }
        let leaf_identities = crate::distinct_struct_identities_by_leaf(&program);
        let mut call_control = crate::call::CallControl::new();
        crate::bind_trait_default_direct_paths(&program, &mut call_control, &leaf_identities);
        let graph = call_control
            .function_graphs()
            .get(&crate::CallPath::from_segments([
                "OpcodeStepExecutor",
                "to_bool",
            ]))
            .expect("direct path registered");
        assert!(
            to_bool_default && to_bool_override,
            "LLBC must contain both the trait default and the PyFrame override; \
             owners={owners:?} ids={}",
            ids.len()
        );
        assert_eq!(
            ids.len(),
            1,
            "OpcodeStepExecutor owners must be one struct identity; owners={owners:?}"
        );
        assert!(
            graph.name.contains("eval") && graph.name.contains("<Impl>"),
            "direct to_bool graph is {:?}; owners={owners:?} ({} strings, {} struct ids); \
             classified_override={to_bool_override}",
            graph.name,
            owners.len(),
            ids.len()
        );
        assert!(
            !graph.name.contains("OpcodeStepExecutor"),
            "raising default stayed on the direct path: {}",
            graph.name
        );
    }

    /// `range_list_length` stores the PyPy strategy length in an RPython
    /// Signed cell and converts it to Rust's indexing carrier.  The opaque
    /// core `TryFrom` shell must be decomposed by the MIR front rather than
    /// surviving as a residual foreign call that blocks the whole list
    /// strategy closure.
    #[test]
    #[ignore]
    fn range_list_length_lowers_signed_to_usize_try_from() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../build/llbc/pyre-object.ullbc"
        );
        let llbc = Llbc::load(path).expect("load real object LLBC");
        let source = super::lower_function(&llbc, "pyre_object::listobject::range_state_value")
            .expect("lower listobject::range_state_value");
        assert!(
            source
                .blocks
                .iter()
                .flat_map(|block| &block.operations)
                .any(|op| matches!(
                    &op.kind,
                    OpKind::ArrayRead {
                        item_ty: ValueType::Int,
                        array_type_id: Some(array_type_id),
                        ..
                    } if array_type_id == "[i64]"
                )),
            "TypedItemsBlock i64 dereference must be a GcArray(Signed) read"
        );
        let graph = super::lower_function(&llbc, "pyre_object::listobject::range_list_length")
            .expect("lower listobject::range_list_length");
        let residuals: Vec<_> = graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .filter_map(|op| match &op.kind {
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } if segments
                    .iter()
                    .any(|segment| segment == "ptr_try_from_impls") =>
                {
                    Some(segments.join("::"))
                }
                _ => None,
            })
            .collect();
        assert!(
            residuals.is_empty(),
            "signed-to-usize conversion must not leave an opaque core call: {residuals:?}"
        );
        let unwrap_residuals = graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call {
                        target: CallTarget::Method { name, .. },
                        ..
                    } if name == "unwrap"
                )
            })
            .count();
        assert_eq!(
            unwrap_residuals, 0,
            "checked conversion Result::unwrap must become a discriminant guard"
        );
        for name in [
            "pyre_object::listobject::range_state_value",
            "pyre_object::listobject::range_list_length",
            "pyre_object::listobject::range_list_start_step",
            "pyre_object::listobject::sizehint_state_value",
        ] {
            let lowered = super::lower_function(&llbc, name).unwrap_or_else(|err| {
                panic!("lower {name}: {err:?}");
            });
            let raw_loads: Vec<_> = lowered
                .blocks
                .iter()
                .flat_map(|block| &block.operations)
                .filter(|op| matches!(op.kind, OpKind::RawLoad { .. }))
                .collect();
            assert!(
                raw_loads.is_empty(),
                "{name}: a TypedItemsBlock word is getarrayitem, not raw_load: {raw_loads:?}"
            );
            if name.ends_with("sizehint_state_value") {
                let ret = lowered
                    .blocks
                    .iter()
                    .flat_map(|block| &block.exits)
                    .find(|link| link.target == lowered.returnblock)
                    .and_then(|link| link.args.first())
                    .and_then(crate::model::LinkArg::as_variable)
                    .cloned()
                    .expect("sizehint_state_value returns the loaded word");
                let mut current = ret;
                let mut producer = None;
                for _ in 0..32 {
                    if let Some(op) = lowered.blocks.iter().find_map(|block| {
                        block.operations.iter().find_map(|op| {
                            (op.result.as_ref() == Some(&current)).then_some(&op.kind)
                        })
                    }) {
                        producer = Some(op);
                        break;
                    }
                    let mut next = None;
                    for block in &lowered.blocks {
                        let Some(slot) = block.inputargs.iter().position(|arg| arg == &current)
                        else {
                            continue;
                        };
                        for pred in &lowered.blocks {
                            for exit in &pred.exits {
                                if exit.target == block.id
                                    && let Some(src) =
                                        exit.args.get(slot).and_then(|arg| arg.as_variable())
                                    && src != &current
                                {
                                    next = Some(src.clone());
                                }
                            }
                        }
                    }
                    match next {
                        Some(src) => current = src,
                        None => break,
                    }
                }
                assert!(
                    matches!(
                        producer,
                        Some(OpKind::ArrayRead {
                            item_ty: ValueType::Int,
                            array_type_id: Some(array_type_id),
                            ..
                        }) if array_type_id == "[i64]"
                    ),
                    "{name}: returned word must be the index-0 Signed read, got {producer:?}"
                );
            }
        }
        let store =
            super::lower_function(&llbc, "pyre_object::listobject::set_sizehint_state_value")
                .expect("lower set_sizehint_state_value");
        let raw_stores: Vec<_> = store
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .filter(|op| matches!(op.kind, OpKind::RawStore { .. }))
            .collect();
        assert!(
            raw_stores.is_empty(),
            "set_sizehint_state_value must not raw_store a GcArray cell: {raw_stores:?}"
        );
        assert!(
            store
                .blocks
                .iter()
                .flat_map(|block| &block.operations)
                .any(|op| matches!(
                    &op.kind,
                    OpKind::ArrayWrite {
                        item_ty: ValueType::Int,
                        array_type_id: Some(array_type_id),
                        ..
                    } if array_type_id == "[i64]"
                )),
            "set_sizehint_state_value must setarrayitem the Signed cell"
        );
    }

    /// `complex_val` returns the RPython spelling of an optional pair.  The
    /// arithmetic helpers call `unwrap` only after their numeric dispatch has
    /// established the value is present, so the opaque Rust combinator must be
    /// translated to the ordinary payload guard instead of becoming a method
    /// lookup on an Option shell.
    #[test]
    #[ignore]
    fn complex_arithmetic_unwraps_lower_to_payload_guards() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../build/llbc/pyre-interpreter.ullbc"
        );
        let llbc = Llbc::load(path).expect("load real interpreter LLBC");
        for name in [
            "pyre_interpreter::objspace::descroperation::complex_add",
            "pyre_interpreter::objspace::descroperation::complex_sub",
            "pyre_interpreter::objspace::descroperation::complex_mul",
            "pyre_interpreter::objspace::descroperation::complex_truediv",
            "pyre_interpreter::objspace::descroperation::complex_neg",
        ] {
            let graph = super::lower_function(&llbc, name)
                .unwrap_or_else(|err| panic!("lower {name}: {err:?}"));
            let residuals: Vec<_> = graph
                .blocks
                .iter()
                .enumerate()
                .flat_map(|(block, bb)| {
                    bb.operations.iter().filter_map(move |op| match &op.kind {
                        OpKind::Call {
                            target: CallTarget::Method { name, .. },
                            ..
                        } if name == "unwrap" => Some((block, op.clone(), bb.exits.clone())),
                        _ => None,
                    })
                })
                .collect();
            assert!(
                residuals.is_empty(),
                "{name}: Option::unwrap must become a payload guard: {residuals:#?}"
            );
        }
    }

    /// The unwrapped-list storage adapters are Rust spellings of
    /// RPython's `l.items` GcArray.  A live `push` must therefore end in the
    /// same `setarrayitem` shape as `rlist.ll_append_noresize`, never in the
    /// synthetic raw-pointer write that blocks annotation.  The adapter body
    /// itself must also be free of the opaque Rust `offset_of!` getter; its
    /// target-layout constant is part of the translated GcArray shape.
    #[test]
    #[ignore]
    fn unwrapped_array_pushes_lower_to_rpython_gcarray_writes() {
        use crate::model::{CallTarget, OpKind};

        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../build/llbc/pyre-object.ullbc"
        );
        let llbc = Llbc::load(path).expect("load real object LLBC");
        // `offset_leaf` is `None` for the two string rows on purpose: their
        // `base` is `items_block_items_base(self.block)`, a call with no
        // offset constant in the body, so a "no surviving offset read"
        // assertion over them would hold whatever the fold did.  Their real
        // content is the `push` half below.
        for (base, function, expected_array, expected_item, offset_leaf) in [
            (
                "pyre_object::int_array::<Impl>::base",
                "pyre_object::int_array::<Impl>::push",
                "[i64]",
                ValueType::Int,
                Some("TYPED_ITEMS_BLOCK_ITEMS_OFFSET"),
            ),
            (
                "pyre_object::float_array::<Impl>::base",
                "pyre_object::float_array::<Impl>::push",
                "[f64]",
                ValueType::Float,
                Some("TYPED_ITEMS_BLOCK_ITEMS_OFFSET"),
            ),
            (
                "pyre_object::bytes_array::<Impl>::base",
                "pyre_object::bytes_array::<Impl>::push",
                super::STRING_GCREF_GCARRAY_TYPE_ID,
                ValueType::Str,
                None,
            ),
            (
                "pyre_object::unicode_array::<Impl>::base",
                "pyre_object::unicode_array::<Impl>::push",
                super::STRING_GCREF_GCARRAY_TYPE_ID,
                ValueType::Str,
                None,
            ),
        ] {
            if let Some(offset_leaf) = offset_leaf {
                let base_graph = super::lower_function(&llbc, base)
                    .unwrap_or_else(|err| panic!("lower {base}: {err}"));
                assert!(
                    !base_graph
                        .blocks
                        .iter()
                        .flat_map(|block| &block.operations)
                        .any(|op| matches!(
                            &op.kind,
                            OpKind::Call {
                                target: CallTarget::FunctionPath { segments, .. },
                                ..
                            } if segments.last().is_some_and(|leaf| leaf == offset_leaf)
                        )),
                    "{base} must fold the target-layout items offset"
                );
            }
            let graph = super::lower_function(&llbc, function)
                .unwrap_or_else(|err| panic!("lower {function}: {err}"));
            let operations: Vec<_> = graph
                .blocks
                .iter()
                .flat_map(|block| &block.operations)
                .collect();
            assert!(
                operations.iter().any(|op| matches!(
                    &op.kind,
                    OpKind::ArrayWrite {
                        item_ty,
                        array_type_id: Some(array_type_id),
                        ..
                    } if array_type_id == expected_array && item_ty == &expected_item
                )),
                "{function} must write {expected_array}/{expected_item:?} through setarrayitem"
            );
            assert!(
                !operations.iter().any(|op| matches!(
                    &op.kind,
                    OpKind::Call {
                        target: CallTarget::FunctionPath { segments, .. },
                        ..
                    } if segments == &["__deref_write".to_string()]
                )),
                "{function} must not retain a raw-pointer write"
            );
        }

        for function in [
            "pyre_object::bytes_array::<Impl>::as_slice",
            "pyre_object::unicode_array::<Impl>::as_slice",
        ] {
            let graph = super::lower_function(&llbc, function)
                .unwrap_or_else(|err| panic!("lower {function}: {err}"));
            assert!(
                !graph
                    .blocks
                    .iter()
                    .flat_map(|block| &block.operations)
                    .any(|op| matches!(
                        &op.kind,
                        OpKind::Call {
                            target: CallTarget::FunctionPath { segments, .. },
                            ..
                        } if segments.last().is_some_and(|leaf| leaf == "from_raw_parts")
                    )),
                "{function} must be the direct RPython list-items view"
            );
        }

        for function in [
            "pyre_object::bytes_array::<Impl>::pop",
            "pyre_object::unicode_array::<Impl>::pop",
            "pyre_object::bytes_array::<Impl>::remove",
            "pyre_object::unicode_array::<Impl>::remove",
        ] {
            let graph = super::lower_function(&llbc, function)
                .unwrap_or_else(|err| panic!("lower {function}: {err}"));
            let operations: Vec<_> = graph
                .blocks
                .iter()
                .flat_map(|block| &block.operations)
                .collect();
            assert!(
                operations.iter().any(|operation| matches!(
                    &operation.kind,
                    OpKind::ArrayRead {
                        item_ty: ValueType::Str,
                        array_type_id: Some(array_type_id),
                        ..
                    } if array_type_id == super::STRING_GCREF_GCARRAY_TYPE_ID
                )),
                "{function} must read its external string through GcArray(GCREF)"
            );
            assert!(
                operations.iter().any(|operation| matches!(
                    &operation.kind,
                    OpKind::ArrayWrite {
                        item_ty: ValueType::Str,
                        array_type_id: Some(array_type_id),
                        ..
                    } if array_type_id == super::STRING_GCREF_GCARRAY_TYPE_ID
                )),
                "{function} must clear the released slot through the same GcArray(GCREF)"
            );
            assert!(
                !operations.iter().any(|operation| matches!(
                    &operation.kind,
                    OpKind::Call {
                        target: CallTarget::FunctionPath { segments, .. },
                        ..
                    } if segments.last().is_some_and(|leaf| {
                        leaf == "from_raw_parts" || leaf == "__deref_write"
                    })
                )),
                "{function} must not retain a Rust raw-slice/read-write boundary"
            );
            if function.ends_with("::remove") {
                assert!(
                    operations.iter().any(|operation| matches!(
                        &operation.kind,
                        OpKind::Call {
                            target: CallTarget::FunctionPath { segments, .. },
                            ..
                        } if segments == &[crate::runtime_names::shims::LL_ARRAYMOVE.to_string()]
                    )),
                    "{function} must restore ptr::copy to RPython rgc.ll_arraymove"
                );
                assert!(
                    !operations.iter().any(|operation| matches!(
                        &operation.kind,
                        OpKind::Call {
                            target: CallTarget::FunctionPath { segments, .. },
                            ..
                        } if segments.as_slice() == ["core", "ptr", "copy"]
                            || segments.as_slice() == ["core", "ptr", "mut_ptr", "<Impl>", "add"]
                    )),
                    "{function} must not retain Rust pointer-copy arithmetic"
                );
            }
        }
    }

    /// `opcode_for_iter` matches `Option<H::Value>`. The sole impl binds
    /// `Value = *mut PyObject`, a null niche. The generic body spells that
    /// payload as a trait projection; the discriminant must be a null test.
    #[test]
    #[ignore]
    fn opcode_for_iter_option_assoc_payload_is_null_test() {
        use crate::model::OpKind;
        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real interpreter LLBC");
        let graph = super::lower_function(&llbc, "pyre_interpreter::pyopcode::opcode_for_iter")
            .expect("lower opcode_for_iter");
        let null_muts = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(&op.kind, OpKind::Call { target, .. }
                    if target.to_string() == "core::ptr::null_mut")
            })
            .count();
        assert!(
            null_muts >= 1,
            "opcode_for_iter Option match must null-test the pointer (null_muts={null_muts})"
        );
    }

    #[test]
    fn niche_option_non_niche_payloads_remain_aggregate() {
        let scalar_ptr = serde_json::json!({
            "RawPtr": [{"Scalar": {"Integer": {"Unsigned": "U8"}}}, "Mut"]
        });
        let tuple = serde_json::json!({
            "Adt": {
                "id": 0, "builtin": "Tuple",
                "generics": {
                    "regions": [],
                    "types": [
                        {"Scalar": {"Integer": {"Signed": "I64"}}},
                        { "Scalar": "Bool" }
                    ],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        });
        let cases = [
            (
                "raw_scalar_ptr",
                scalar_ptr,
                "Option<*mut u8> must not collapse None to the payload null word",
                "Option<*mut u8> must retain the tagged Some and None aggregates",
            ),
            (
                "tuple",
                tuple,
                "Option<(i64, bool)> must not collapse None to a payload null word",
                "Option<(i64, bool)> must retain the tagged Some and None aggregates",
            ),
        ];
        for (name, payload, none_msg, agg_msg) in cases {
            let graph = lower_option_source_with_payload(payload);
            let (null_muts, transparent_ctors) = niche_ctor_shape(&graph);
            assert_eq!(null_muts, 0, "case {name}: {none_msg}");
            assert!(transparent_ctors >= 2, "case {name}: {agg_msg}");
        }
    }

    /// `Option<String>` match is RPython's nullable `SomeString`:
    /// `s is None` (`pairtype(SomeObject, SomeObject).is_`, rtyped by
    /// `rtype_is_` / `ptr_iszero`), and the `Some` payload is the string
    /// itself. The corpus `option_question_mark` `?` is a `Try::branch`
    /// match; injecting `alloc::string::String` as the Option payload
    /// pins that the front does not emit `getattr('__discriminant')`.
    #[test]
    fn niche_option_string_match_is_none_identity() {
        use crate::model::OpKind;
        let graph = lower_option_fn_retyped(
            "option_question_mark",
            serde_json::Value::Null,
            false,
            false,
            true,
        );
        let (null_muts, transparent_ctors) = niche_ctor_shape(&graph);
        assert!(
            null_muts >= 1,
            "Option<String> None must lower to a null string pointer, got {null_muts}"
        );
        assert_eq!(
            transparent_ctors, 0,
            "Option<String> Some must be the string identity, with no Option aggregate"
        );
        let discriminant_reads = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(&op.kind, OpKind::FieldRead { field, .. } if field.name == "__discriminant")
            })
            .count();
        assert_eq!(
            discriminant_reads, 0,
            "Option<String> match must not read an aggregate __discriminant"
        );
        let some_payload_reads = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::FieldRead { field, .. }
                        if field.name == "__pos_0"
                            && field.owner_root.as_deref().is_some_and(|owner| {
                                owner.contains("Option") && owner.ends_with("::Some")
                            })
                )
            })
            .count();
        assert_eq!(
            some_payload_reads, 0,
            "Option<String> Some payload must be the string itself"
        );
        let has_is = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .any(|op| matches!(&op.kind, OpKind::BinOp { op, .. } if op == "is_"));
        assert!(
            has_is,
            "Option<String> match must contain an identity null-test"
        );
    }

    /// `Option<&[u8]>` None is `convert_const(None)` on `StringRepr`. The
    /// cast root keeps the shared borrow so `project_struct_field_type`
    /// projects `s_str0`. `Option<&mut [u8]>` is a list of unsigned.
    #[test]
    fn option_niche_null_cast_shared_u8_slice_is_str() {
        use crate::model::ValueType;

        let llbc = llbc_with_types("fixture", vec![option_enum(0)], vec![]);
        let span = serde_json::json!({"data": {
            "file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}
        }});
        let body: super::Unstructured = serde_json::from_value(serde_json::json!({
            "locals": {"arg_count": 0, "locals": []}, "body": [], "span": span
        }))
        .unwrap();
        let dont_look_inside = std::collections::HashSet::new();
        let accum = super::AccumulatorFacts::build(&llbc, &body);
        let tombstoned = std::collections::HashSet::new();
        let gc_struct_ids_llbc = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        let lowering = super::Lowering::new(
            &llbc,
            "fixture".into(),
            &body,
            crate::HostStaticAddrs::default(),
            &[],
            None,
            &dont_look_inside,
            &tombstoned,
            &gc_struct_ids_llbc,
            &accum,
            &super::RootStackAnalyzer::new(&llbc, &super::RootStackState::new(&llbc)),
            false,
            false,
        )
        .unwrap();
        let u8_ty = serde_json::json!({"Scalar": {"Integer": {"Unsigned": "U8"}}});
        let slice = serde_json::json!({"Slice": [u8_ty, null]});
        let option_shared = TyRef::Other(option_adt_node(
            0,
            serde_json::json!({"Ref": ["Erased", slice.clone(), "Shared"]}),
        ));
        let option_mut = TyRef::Other(option_adt_node(
            0,
            serde_json::json!({"Ref": ["Erased", slice, "Mut"]}),
        ));
        assert_eq!(
            lowering.option_niche_null_cast(&option_shared),
            Some(("&[u8]".to_string(), ValueType::Str)),
            "Option<&[u8]> None is StringRepr convert_const(None)"
        );
        assert!(
            !matches!(
                lowering.option_niche_null_cast(&option_mut),
                Some((_, ValueType::Str))
            ),
            "Option<&mut [u8]> None is not a string root"
        );
    }

    /// `<Option<&str> as PartialEq>::ne` on two niche nullable strings
    /// (`opt != Some(c)`). `trait_default_call_segments` rewrites
    /// `PartialEq::ne` to `["option", "Option", "ne"]`; the fold emits
    /// string `BinOp("ne")` (`rstr.py` `AbstractStringRepr.rtype_ne` →
    /// `ll_streq`) instead of leaving that FunctionPath residual.
    #[test]
    fn niche_option_str_ne_lowers_to_string_binop() {
        use crate::model::{CallTarget, OpKind};

        let span = serde_json::json!({"data": {"file_id": 0,
            "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}}});
        let meta = |path: &[&str]| {
            serde_json::json!({
                "name": path.iter().map(|s| serde_json::json!({"Ident": [s, 0]})).collect::<Vec<_>>(),
                "span": span, "source_text": null, "is_local": true,
                "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true}
            })
        };
        let generics = serde_json::json!({
            "regions": [], "types": [], "const_generics": [], "trait_refs": []
        });
        let str_ty = serde_json::json!({
            "Adt": {"builtin": "Str", "generics": generics}
        });
        let str_ref = serde_json::json!({"Ref": ["Erased", str_ty, "Shared"]});
        let option_ty = serde_json::json!({
            "Adt": {
                "id": 0,
                "generics": {
                    "regions": [],
                    "types": [str_ref],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        });
        let option_ref = serde_json::json!({"Ref": ["Erased", option_ty, "Shared"]});
        let bool_ty = serde_json::json!({"Scalar": "Bool"});
        let place =
            |id, ty: &serde_json::Value| serde_json::json!({"kind": {"Local": id}, "ty": ty});
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [{
                    "def_id": 0,
                    "item_meta": meta(&["core", "option", "Option"]),
                    "kind": "Opaque"
                }],
                "fun_decls": [
                    {
                        "def_id": 0,
                        "item_meta": meta(&["fixture", "cmp_option_str"]),
                        "signature": {
                            "is_unsafe": false,
                            "inputs": [option_ref.clone(), option_ref.clone()],
                            "output": bool_ty.clone()
                        },
                        "body": {"Unstructured": {"span": span,
                            "locals": {"arg_count": 2, "locals": [
                                {"index": 0, "name": null, "span": span, "ty": bool_ty.clone()},
                                {"index": 1, "name": "lhs", "span": span, "ty": option_ref.clone()},
                                {"index": 2, "name": "rhs", "span": span, "ty": option_ref.clone()},
                                {"index": 3, "name": null, "span": span, "ty": bool_ty.clone()}
                            ]},
                            "body": [
                                {"statements": [], "terminator": {"span": span, "kind": {"Call": {
                                    "call": {
                                        "func": {"Regular": {"kind": {"Fun": 1}, "generics": generics}},
                                        "args": [
                                            {"Copy": place(1, &option_ref)},
                                            {"Copy": place(2, &option_ref)}
                                        ],
                                        "dest": place(3, &bool_ty)
                                    },
                                    "target": 1, "on_unwind": 2
                                }}}},
                                {"statements": [{
                                    "span": span,
                                    "kind": {"Assign": [
                                        place(0, &bool_ty),
                                        {"Use": [{"Copy": place(3, &bool_ty)}, "Yes"]}
                                    ]}
                                }], "terminator": {"span": span, "kind": "Return"}},
                                {"statements": [], "terminator": {"span": span, "kind": "UnwindResume"}}
                            ]
                        }}
                    },
                    {
                        "def_id": 1,
                        "item_meta": meta(&["core", "option", "Option", "ne"]),
                        "signature": {
                            "is_unsafe": false,
                            "inputs": [option_ref.clone(), option_ref.clone()],
                            "output": bool_ty
                        },
                        "body": "Opaque"
                    }
                ],
                "global_decls": [],
                "trait_decls": [],
                "trait_impls": []
            }
        });
        let llbc =
            Llbc::from_slice(file.to_string().as_bytes()).expect("option-str fixture parses");
        let graph = super::lower_function(&llbc, "cmp_option_str").expect("lower cmp_option_str");
        let ops = || graph.blocks.iter().flat_map(|b| b.operations.iter());
        assert_eq!(
            ops()
                .filter(|op| match &op.kind {
                    OpKind::Call {
                        target: CallTarget::FunctionPath { segments, .. },
                        ..
                    } => super::fmt_path_ends_with(segments, &["Option", "ne"]),
                    _ => false,
                })
                .count(),
            0,
            "no residual `Option::ne` call survives the string-niche fold"
        );
        assert!(
            ops().any(|op| matches!(&op.kind, OpKind::BinOp { op, .. } if op == "ne")),
            "the comparison lowers to a string `BinOp(ne)`"
        );
    }

    /// `opt == Some(p)` on niche `Option<*mut T>`. Charon spells the
