    #[test]
    fn mut_ref_cell_root_names_a_gc_pointer_only() {
        let llbc = fixture_llbc();
        let tomb = no_tombstoned_leaves();
        let gc = std::collections::HashSet::new();
        let i64 = serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}});
        let i64_ty: TyRef = serde_json::from_value(i64.clone()).unwrap();
        assert!(super::mut_ref_cell_root_of(&i64_ty, &llbc, tomb, &gc).is_none());
        let raw_i64: TyRef =
            serde_json::from_value(serde_json::json!({"RawPtr": [i64, "Mut"]})).unwrap();
        assert!(super::mut_ref_cell_root_of(&raw_i64, &llbc, tomb, &gc).is_none());
        let obj = serde_json::json!({"Adt": {"id": 7}});
        let obj_ty: TyRef = serde_json::from_value(obj.clone()).unwrap();
        assert!(super::mut_ref_cell_root_of(&obj_ty, &llbc, tomb, &gc).is_none());
        let raw_obj: TyRef =
            serde_json::from_value(serde_json::json!({"RawPtr": [obj, "Mut"]})).unwrap();
        assert_eq!(
            super::mut_ref_cell_root_of(&raw_obj, &llbc, tomb, &gc).as_deref(),
            Some("MutRef<*mut ??adt#7>")
        );
    }

    /// A cell parameter's startblock input is the `MutRef<T>` class, not the
    /// pointee. A `dont_look_inside` subject keeps the raw word.
    #[test]
    fn mut_ref_cell_param_input_names_the_cell_unless_residual() {
        use crate::model::OpKind;

        let llbc = fixture_llbc();
        let tomb = no_tombstoned_leaves();
        let gc_struct_ids = std::collections::HashSet::new();
        let span = serde_json::json!({"data": {
            "file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}
        }});
        let pointee = serde_json::json!({"RawPtr": [{"Adt": {"id": 7}}, "Mut"]});
        let mut_ref = serde_json::json!({"Ref": ["Erased", pointee, "Mut"]});
        let locals: majit_charon_reader::ullbc::Locals =
            serde_json::from_value(serde_json::json!({
                "arg_count": 1,
                "locals": [
                    {
                        "index": 0,
                        "name": null,
                        "span": span,
                        "ty": {"Scalar": {"Integer": {"Signed": "I64"}}}
                    },
                    {"index": 1, "name": "slot", "span": span, "ty": mut_ref}
                ]
            }))
            .unwrap();
        let pointee_ty: TyRef = serde_json::from_value(pointee).unwrap();
        let root = super::mut_ref_cell_root_of(&pointee_ty, &llbc, tomb, &gc_struct_ids)
            .expect("raw GC pointer behind &mut is a cell");
        let slot = |graph: &FunctionGraph| {
            graph
                .block(graph.startblock)
                .operations
                .iter()
                .find(|op| matches!(&op.kind, OpKind::Input { name, .. } if name == "slot"))
                .expect("slot input")
                .clone()
        };

        let cells = super::gc_mut_ref_param_locals(&locals, &llbc, tomb, &gc_struct_ids, false);
        assert!(cells.contains(&1));
        let mut graph = FunctionGraph::new("c::holder");
        super::pygraph_initial_block(
            &mut graph,
            &locals,
            &llbc,
            None,
            tomb,
            &cells,
            &gc_struct_ids,
            false,
        );
        let OpKind::Input { ty, class_root, .. } = &slot(&graph).kind else {
            panic!("slot op is an input");
        };
        assert_eq!(class_root.as_deref(), Some(root.as_str()));
        assert_eq!(ty, &ValueType::Ref(Some(root)));

        let residual = super::gc_mut_ref_param_locals(&locals, &llbc, tomb, &gc_struct_ids, true);
        assert!(residual.is_empty());
        let mut residual_graph = FunctionGraph::new("c::holder");
        super::pygraph_initial_block(
            &mut residual_graph,
            &locals,
            &llbc,
            None,
            tomb,
            &residual,
            &gc_struct_ids,
            false,
        );
        let OpKind::Input { class_root, .. } = &slot(&residual_graph).kind else {
            panic!("slot op is an input");
        };
        assert!(
            !class_root.as_deref().unwrap_or("").starts_with("MutRef<"),
            "a residual subject's parameter keeps the raw word"
        );
    }

    /// A residual callee — no body, or `dont_look_inside` — is not given a
    /// cell signature. The traced callee with the same `&mut` GC pointer is.
    #[test]
    fn mut_ref_cell_signature_skips_a_residual_callee() {
        let span = serde_json::json!({"data": {
            "file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}
        }});
        let mut_ref = serde_json::json!({
            "Ref": ["Erased", {"RawPtr": [{"Adt": {"id": 7}}, "Mut"]}, "Mut"]
        });
        let item = |leaf: &str| {
            serde_json::json!({
                "name": [
                    {"Ident": ["fixture", 0]},
                    {"Ident": [leaf, 0]}
                ],
                "span": span.clone(),
                "source_text": null,
                "attr_info": {
                    "attributes": [],
                    "inline": null,
                    "rename": null,
                    "public": true
                },
                "is_local": true
            })
        };
        let signature = serde_json::json!({
            "is_unsafe": false,
            "inputs": [mut_ref],
            "output": {"Tuple": []}
        });
        let body = serde_json::json!({
            "Unstructured": {
                "locals": {"arg_count": 0, "locals": []},
                "body": [],
                "span": span.clone()
            }
        });
        let decl = |id: u64, leaf: &str, body: serde_json::Value| {
            serde_json::json!({
                "def_id": id,
                "item_meta": item(leaf),
                "signature": signature.clone(),
                "body": body
            })
        };
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [],
                "fun_decls": [
                    decl(0, "traced", body.clone()),
                    decl(1, "opaque", serde_json::Value::Null),
                    decl(2, "marked", body)
                ],
                "global_decls": [],
                "trait_decls": [],
                "trait_impls": []
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture parses");
        let mut dont_look_inside = std::collections::HashSet::new();
        dont_look_inside.insert("marked".to_string());
        assert!(!super::fun_decl_is_residual(
            llbc.fn_by_id(0).unwrap(),
            &dont_look_inside
        ));
        assert!(super::fun_decl_is_residual(
            llbc.fn_by_id(1).unwrap(),
            &dont_look_inside
        ));
        assert!(super::fun_decl_is_residual(
            llbc.fn_by_id(2).unwrap(),
            &dont_look_inside
        ));

        let subject: super::Unstructured = serde_json::from_value(serde_json::json!({
            "locals": {"arg_count": 0, "locals": []},
            "body": [],
            "span": span
        }))
        .unwrap();
        let accum = super::AccumulatorFacts::build(&llbc, &subject);
        let tombstoned_leaves = std::collections::HashSet::new();
        let gc_struct_ids = std::collections::HashSet::new();
        let lowering = super::Lowering::new(
            &llbc,
            "fixture::holder".into(),
            &subject,
            crate::HostStaticAddrs::default(),
            &[],
            None,
            &dont_look_inside,
            &tombstoned_leaves,
            &gc_struct_ids,
            &accum,
            &super::RootStackAnalyzer::new(&llbc, &super::RootStackState::new(&llbc)),
            false,
            false,
        )
        .unwrap();
        let call = |id: u64| {
            serde_json::from_value::<super::CallFunc>(serde_json::json!({
                "Regular": {
                    "kind": {"Fun": id},
                    "generics": {
                        "regions": [],
                        "types": [],
                        "const_generics": [],
                        "trait_refs": []
                    }
                }
            }))
            .unwrap()
        };
        let traced = lowering
            .gc_mut_ref_signature(&call(0), &[])
            .expect("a traced &mut GC pointer is a cell");
        assert_eq!(traced.0, Some(0));
        assert!(traced.1[0].1.starts_with("MutRef<"));
        assert!(lowering.gc_mut_ref_signature(&call(1), &[]).is_none());
        assert!(lowering.gc_mut_ref_signature(&call(2), &[]).is_none());
    }

    /// `&mut PyObjectRef` parameters are one-field GC cells. Stores and
    /// loads of `*lhs` / `*rhs` are field operations on `MutRef<…>`, and
    /// the pointer word is not a raw load or store.
    /// Ignored by default (loads the real LLBC).
    #[test]
    #[ignore]
    fn mut_ref_cell_try_dispatch_binary_special() {
        use crate::model::{OpKind, ValueType};

        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph = super::lower_function(
            &llbc,
            "pyre_interpreter::objspace::descroperation::try_dispatch_binary_special",
        )
        .expect("lower try_dispatch_binary_special");
        let ops = || {
            graph
                .blocks
                .iter()
                .flat_map(|block| block.operations.iter())
        };
        assert!(
            ops()
                .all(|op| { !matches!(op.kind, OpKind::RawStore { .. } | OpKind::RawLoad { .. }) }),
            "a GC-reference `&mut` cell does not raw-load or raw-store the pointer word"
        );
        assert!(
            ops().any(|op| matches!(
                &op.kind,
                OpKind::FieldWrite { field, .. } if mut_ref_value_field(field)
            )),
            "stores through the cell write the `value` field"
        );
        assert!(
            ops().any(|op| matches!(
                &op.kind,
                OpKind::FieldRead { field, .. } if mut_ref_value_field(field)
            )),
            "reads through the cell read the `value` field"
        );
        let start = graph.block(graph.startblock);
        let mut cell_params = 0usize;
        for op in &start.operations {
            let OpKind::Input {
                name,
                ty,
                class_root,
            } = &op.kind
            else {
                continue;
            };
            if name != "lhs" && name != "rhs" {
                continue;
            }
            let root = class_root.as_deref().unwrap_or("");
            assert!(
                root.starts_with("MutRef<"),
                "{name} class_root {root:?} is not the cell"
            );
            assert_eq!(ty, &ValueType::Ref(Some(root.to_string())), "{name}");
            cell_params += 1;
        }
        assert_eq!(cell_params, 2, "lhs and rhs are the cell parameters");
    }

    /// `sub_impl` passes `&mut a` / `&mut b` into
    /// `try_dispatch_binary_special`. The cell is built in the caller,
    /// passed as the argument, and read back into the local after the call.
    /// Ignored by default (loads the real LLBC).
    #[test]
    #[ignore]
    fn mut_ref_cell_copy_sub_impl() {
        use crate::model::{CallTarget, OpKind};

        let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
        let llbc = Llbc::load(path).expect("load real LLBC");
        let graph = super::lower_function(
            &llbc,
            "pyre_interpreter::objspace::descroperation::sub_impl",
        )
        .expect("lower sub_impl");
        let mut found = false;
        for block in &graph.blocks {
            let ops = &block.operations;
            for (idx, op) in ops.iter().enumerate() {
                let OpKind::Call { target, .. } = &op.kind else {
                    continue;
                };
                if !target_is_try_dispatch(target) {
                    continue;
                }
                let before = ops[..idx].iter().any(|earlier| {
                    matches!(
                        &earlier.kind,
                        OpKind::Call {
                            target: CallTarget::SyntheticTransparentCtor { name, .. },
                            ..
                        } if name.starts_with("MutRef<")
                    )
                });
                let after = ops[idx + 1..].iter().any(|later| {
                    matches!(
                        &later.kind,
                        OpKind::FieldRead { field, .. } if mut_ref_value_field(field)
                    )
                });
                if before && after {
                    found = true;
                    break;
                }
            }
            if found {
                break;
            }
        }
        assert!(
            found,
            "a MutRef constructor precedes try_dispatch_binary_special and a value FieldRead follows it in the same block"
        );
    }

    fn mut_ref_value_field(field: &FieldDescriptor) -> bool {
        field.name == "value"
            && field
                .owner_root
                .as_deref()
                .is_some_and(|owner| owner.starts_with("MutRef<"))
    }

    fn target_is_try_dispatch(target: &CallTarget) -> bool {
        match target {
            CallTarget::FunctionPath { segments, .. } => {
                super::fmt_path_ends_with(segments, &["try_dispatch_binary_special"])
            }
            CallTarget::Method { name, .. } => name == "try_dispatch_binary_special",
            _ => false,
        }
    }

    /// `&mut self` on a transparent GC handle is a FunctionPath cell call.
    /// `&self` on the same type stays `CallTarget::Method`.
    #[test]
    fn mut_ref_gc_handle_method_is_function_path_cell() {
        use crate::model::{CallTarget, OpKind};

        let span = serde_json::json!({"data": {
            "file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}
        }});
        let meta = |path: Vec<serde_json::Value>, is_local: bool| {
            serde_json::json!({
                "name": path,
                "span": span,
                "source_text": null,
                "attr_info": {
                    "attributes": [],
                    "inline": null,
                    "rename": null,
                    "public": true
                },
                "is_local": is_local
            })
        };
        let ident = |name: &str| serde_json::json!({"Ident": [name, 0]});
        let adt = |id: u64| {
            serde_json::json!({
                "Adt": {
                    "id": id,
                    "generics": {
                        "regions": [],
                        "types": [],
                        "const_generics": [],
                        "trait_refs": []
                    }
                }
            })
        };
        let payload_ty = adt(1);
        let handle_ty = adt(0);
        let mut_self = serde_json::json!({"Ref": ["Erased", handle_ty.clone(), "Mut"]});
        let shared_self = serde_json::json!({"Ref": ["Erased", handle_ty.clone(), "Shared"]});
        let unit = serde_json::json!({"Tuple": []});
        let layout = |transparent: bool| {
            serde_json::json!([{
                "key": "fixture-target",
                "value": {
                    "size": 8,
                    "align": 8,
                    "variant_layouts": [{"field_offsets": [0]}],
                    "repr": {"transparent": transparent}
                }
            }])
        };
        let field = |name: Option<&str>, ty: serde_json::Value| serde_json::json!({"name": name, "ty": ty, "attr_info": null});
        let impl_seg = serde_json::json!({"Impl": {"Ty": {
            "skip_binder": {"Value": [0, handle_ty.clone()]},
            "kind": "InherentImplBlock"
        }}});
        let local = |index: u64, name: Option<&str>, ty: &serde_json::Value| {
            serde_json::json!({
                "index": index,
                "name": name,
                "span": span,
                "ty": ty
            })
        };
        let place = |index: u64, ty: &serde_json::Value| serde_json::json!({"kind": {"Local": index}, "ty": ty});
        let method_body = |self_ty: &serde_json::Value| {
            serde_json::json!({
                "Unstructured": {
                    "span": span,
                    "locals": {
                        "arg_count": 1,
                        "locals": [
                            local(0, None, &unit),
                            local(1, Some("self"), self_ty)
                        ]
                    },
                    "body": [{
                        "statements": [],
                        "terminator": {"span": span, "kind": "Return"}
                    }]
                }
            })
        };
        let method_decl = |id: u64, leaf: &str, self_ty: &serde_json::Value| {
            serde_json::json!({
                "def_id": id,
                "item_meta": meta(vec![
                    ident("fixture"),
                    ident("Handle"),
                    impl_seg.clone(),
                    ident(leaf),
                ], true),
                "signature": {
                    "is_unsafe": false,
                    "inputs": [self_ty.clone()],
                    "output": unit
                },
                "body": method_body(self_ty)
            })
        };
        let caller = serde_json::json!({
            "def_id": 0,
            "item_meta": meta(vec![ident("fixture"), ident("caller")], true),
            "signature": {
                "is_unsafe": false,
                "inputs": [handle_ty.clone()],
                "output": unit
            },
            "body": {
                "Unstructured": {
                    "span": span,
                    "locals": {
                        "arg_count": 1,
                        "locals": [
                            local(0, None, &unit),
                            local(1, Some("h"), &handle_ty),
                            local(2, None, &mut_self),
                            local(3, None, &shared_self)
                        ]
                    },
                    "body": [
                        {
                            "statements": [{
                                "span": span,
                                "kind": {"Assign": [
                                    place(2, &mut_self),
                                    {"Ref": {
                                        "place": place(1, &handle_ty),
                                        "kind": "Mut",
                                        "ptr_metadata": null
                                    }}
                                ]}
                            }],
                            "terminator": {
                                "span": span,
                                "kind": {
                                    "Call": {
                                        "call": {
                                            "func": {
                                                "Regular": {
                                                    "kind": {"Fun": 1},
                                                    "generics": {
                                                        "regions": [],
                                                        "types": [],
                                                        "const_generics": [],
                                                        "trait_refs": []
                                                    }
                                                }
                                            },
                                            "args": [{"Move": place(2, &mut_self)}],
                                            "dest": place(0, &unit)
                                        },
                                        "target": 2,
                                        "on_unwind": 1
                                    }
                                }
                            }
                        },
                        {
                            "statements": [],
                            "terminator": {"span": span, "kind": "UnwindResume"}
                        },
                        {
                            "statements": [{
                                "span": span,
                                "kind": {"Assign": [
                                    place(3, &shared_self),
                                    {"Ref": {
                                        "place": place(1, &handle_ty),
                                        "kind": "Shared",
                                        "ptr_metadata": null
                                    }}
                                ]}
                            }],
                            "terminator": {
                                "span": span,
                                "kind": {
                                    "Call": {
                                        "call": {
                                            "func": {
                                                "Regular": {
                                                    "kind": {"Fun": 2},
                                                    "generics": {
                                                        "regions": [],
                                                        "types": [],
                                                        "const_generics": [],
                                                        "trait_refs": []
                                                    }
                                                }
                                            },
                                            "args": [{"Move": place(3, &shared_self)}],
                                            "dest": place(0, &unit)
                                        },
                                        "target": 3,
                                        "on_unwind": 1
                                    }
                                }
                            }
                        },
                        {
                            "statements": [],
                            "terminator": {"span": span, "kind": "Return"}
                        }
                    ]
                }
            }
        });
        let file = serde_json::json!({
            "charon_version": "0.1.201",
            "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [
                    {
                        "def_id": 0,
                        "item_meta": meta(vec![ident("fixture"), ident("Handle")], true),
                        "kind": {"Struct": [field(
                            None,
                            serde_json::json!({"RawPtr": [payload_ty, "Mut"]})
                        )]},
                        "layout": layout(true)
                    },
                    {
                        "def_id": 1,
                        "item_meta": meta(vec![ident("fixture"), ident("Payload")], true),
                        "kind": {"Struct": []}
                    }
                ],
                "fun_decls": [
                    caller,
                    method_decl(1, "set_flag", &mut_self),
                    method_decl(2, "get_flag", &shared_self)
                ],
                "global_decls": [],
                "trait_decls": handle_trait_decls(),
                "trait_impls": [gctype_impl_for_adt(1)]
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture parses");
        let handle: TyRef = serde_json::from_value(handle_ty.clone()).unwrap();
        let mut_ty: TyRef = serde_json::from_value(mut_self.clone()).unwrap();
        let tomb = no_tombstoned_leaves();
        let gc = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        assert!(
            super::mut_ref_cell_root_of(&handle, &llbc, tomb, &gc).is_some(),
            "Handle behind &mut is a cell pointee"
        );
        assert!(
            super::tyref_gc_mut_ref_cell_root(&mut_ty, &llbc, tomb, &gc).is_some(),
            "&mut Handle is a cell parameter"
        );
        let graph = super::lower_function(&llbc, "caller").expect("lower caller");
        let ops: Vec<_> = graph
            .blocks
            .iter()
            .flat_map(|block| block.operations.iter())
            .collect();
        let mut_call = ops
            .iter()
            .find(|op| match &op.kind {
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } => super::fmt_path_ends_with(segments, &["Handle", "set_flag"]),
                _ => false,
            })
            .expect("set_flag is a FunctionPath");
        assert!(
            !ops.iter().any(|op| matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::Method { name, .. },
                    ..
                } if name == "set_flag"
            )),
            "set_flag must not route as Method"
        );
        let mut_idx = ops
            .iter()
            .position(|op| std::ptr::eq(*op, *mut_call))
            .expect("set_flag index");
        assert!(
            ops[..mut_idx].iter().any(|op| matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::SyntheticTransparentCtor { name, .. },
                    ..
                } if name.starts_with("MutRef<")
            )),
            "a MutRef constructor precedes set_flag"
        );
        assert!(
            ops[mut_idx + 1..].iter().any(|op| matches!(
                &op.kind,
                OpKind::FieldRead { field, .. } if mut_ref_value_field(field)
            )),
            "a value FieldRead follows set_flag"
        );
        assert!(
            ops.iter().any(|op| matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::Method { name, .. },
                    ..
                } if name == "get_flag"
            )),
            "get_flag stays CallTarget::Method"
        );
    }

